const FAMILY_GENERATED = {"fam-c-mexi-cheese-enchiladas":{"ingredients":[{"qty":"8","item":"corn tortillas"},{"qty":"3 cups","item":"Monterey Jack and cheddar cheese, shredded"},{"qty":"2 cans (10 oz each)","item":"red enchilada sauce"},{"qty":"1","item":"small onion, finely diced"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"chili powder"},{"qty":"2 tbsp","item":"vegetable oil"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for garnish","item":"chopped cilantro and sour cream"}],"steps":["Preheat oven to 375°F and lightly grease a 9x13 baking dish.","Saute the onion and garlic in oil until soft, then stir in cumin, chili powder, salt and pepper.","Warm the tortillas briefly so they are pliable, then dip each in enchilada sauce.","Fill each tortilla with a handful of cheese and a spoonful of the onion mixture, roll up, and place seam-side down in the dish.","Pour remaining enchilada sauce over the top and cover with the rest of the cheese.","Bake 20-25 minutes until bubbly and the cheese is melted.","Garnish with cilantro and sour cream before serving."],"time":"45 min","serves":4},"fam-c-pumpkin-brownies":{"ingredients":[{"qty":"1 cup","item":"all-purpose flour"},{"qty":"1/2 cup","item":"unsweetened cocoa powder"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1 cup","item":"pumpkin puree"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"2","item":"large eggs"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1 tsp","item":"pumpkin pie spice"},{"qty":"1/2 tsp","item":"baking powder"},{"qty":"1/2 tsp","item":"salt"},{"qty":"3/4 cup","item":"chocolate chips"}],"steps":["Preheat oven to 350°F and line an 8x8 pan with parchment.","Whisk together pumpkin puree, oil, sugar, eggs, and vanilla until smooth.","In a separate bowl, combine flour, cocoa, pumpkin pie spice, baking powder, and salt.","Fold the dry ingredients into the wet until just combined, then stir in the chocolate chips.","Spread the batter into the pan and bake 30-35 minutes until a toothpick comes out with moist crumbs.","Cool completely before cutting into squares."],"time":"45 min","serves":9},"fam-c-black-bean-avocado-salsa":{"ingredients":[{"qty":"1 can (15 oz)","item":"black beans, drained and rinsed"},{"qty":"2","item":"ripe avocados, diced"},{"qty":"1 cup","item":"corn kernels"},{"qty":"1","item":"Roma tomato, diced"},{"qty":"1/4 cup","item":"red onion, finely diced"},{"qty":"1","item":"jalapeño, seeded and minced"},{"qty":"1/4 cup","item":"cilantro, chopped"},{"qty":"2 tbsp","item":"lime juice"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1/2 tsp","item":"ground cumin"},{"qty":"to taste","item":"salt"}],"steps":["In a large bowl combine black beans, corn, tomato, red onion, jalapeño, and cilantro.","Whisk together lime juice, olive oil, cumin, and salt.","Pour the dressing over the bean mixture and toss gently.","Fold in the diced avocado just before serving so it stays intact.","Serve immediately with tortilla chips."],"time":"15 min","serves":6},"fam-c-the-baked-potato":{"ingredients":[{"qty":"4","item":"large russet potatoes"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1 tbsp","item":"coarse salt"},{"qty":"4 tbsp","item":"butter"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"1 cup","item":"cheddar cheese, shredded"},{"qty":"4","item":"green onions, sliced"},{"qty":"to taste","item":"black pepper"}],"steps":["Preheat oven to 425°F and scrub the potatoes clean, then pat dry.","Pierce each potato several times with a fork, rub with olive oil, and sprinkle with coarse salt.","Place directly on the oven rack and bake 50-60 minutes until the skin is crisp and a knife slides in easily.","Slice each potato open lengthwise and fluff the inside with a fork.","Top with butter, sour cream, cheddar, green onions, and black pepper."],"time":"1 hr 5 min","serves":4},"fam-c-ginger-grilled-chicken-satay":{"ingredients":[{"qty":"1.5 lbs","item":"chicken thighs, cut into strips"},{"qty":"2 tbsp","item":"fresh ginger, grated"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1/4 cup","item":"soy sauce"},{"qty":"2 tbsp","item":"brown sugar"},{"qty":"1 tbsp","item":"fish sauce"},{"qty":"1 can (13 oz)","item":"coconut milk"},{"qty":"1/2 cup","item":"peanut butter"},{"qty":"1 tbsp","item":"red curry paste"},{"qty":"1 tbsp","item":"lime juice"},{"qty":"12","item":"bamboo skewers, soaked"}],"steps":["Combine ginger, garlic, soy sauce, brown sugar, fish sauce, and half the coconut milk, then marinate the chicken at least 1 hour.","Make the satay sauce by simmering the remaining coconut milk with peanut butter, curry paste, and lime juice until smooth.","Thread the marinated chicken onto soaked skewers.","Grill over medium-high heat 3-4 minutes per side until charred and cooked through.","Serve hot with the warm peanut satay sauce for dipping."],"time":"1 hr 30 min","serves":4},"fam-c-lauras-moms-chicken-salad":{"ingredients":[{"qty":"3 cups","item":"cooked chicken breast, diced"},{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"2","item":"celery stalks, finely chopped"},{"qty":"1/3 cup","item":"red grapes, halved"},{"qty":"1/4 cup","item":"sliced almonds, toasted"},{"qty":"2","item":"green onions, sliced"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"1 tsp","item":"Dijon mustard"},{"qty":"to taste","item":"salt and pepper"}],"steps":["In a large bowl, whisk together mayonnaise, lemon juice, Dijon mustard, salt, and pepper.","Add the diced chicken, celery, grapes, almonds, and green onions.","Fold everything together until evenly coated.","Chill at least 30 minutes before serving on bread or over greens."],"time":"20 min","serves":4},"fam-c-crackling-fish-tacos-with-chipotle-tarta":{"ingredients":[{"qty":"1.5 lbs","item":"white fish fillets (cod or tilapia)"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"1 cup","item":"cold sparkling water"},{"qty":"1 tsp","item":"baking powder"},{"qty":"1 tsp","item":"paprika"},{"qty":"for frying","item":"vegetable oil"},{"qty":"8","item":"corn tortillas"},{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"2","item":"chipotle peppers in adobo, minced"},{"qty":"2 tbsp","item":"dill pickle relish"},{"qty":"1 tbsp","item":"lime juice"},{"qty":"2 cups","item":"shredded cabbage"}],"steps":["Make the tartar sauce by mixing mayonnaise, chipotle, relish, and lime juice, then refrigerate.","Whisk flour, baking powder, paprika, and salt with sparkling water to form a thin batter.","Heat 2 inches of oil to 375°F.","Cut the fish into strips, dip in the batter, and fry 3-4 minutes until golden and crackling crisp.","Drain the fish on paper towels and warm the tortillas.","Fill each tortilla with fish, shredded cabbage, and a drizzle of chipotle tartar sauce."],"time":"40 min","serves":4},"fam-c-mexican-chicken-pasta-bake":{"ingredients":[{"qty":"12 oz","item":"penne pasta"},{"qty":"2 cups","item":"cooked chicken, shredded"},{"qty":"1 jar (16 oz)","item":"salsa"},{"qty":"1 can (10 oz)","item":"diced tomatoes with green chiles"},{"qty":"1 can (15 oz)","item":"black beans, drained"},{"qty":"1 cup","item":"corn kernels"},{"qty":"1 tbsp","item":"taco seasoning"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"2 cups","item":"Mexican cheese blend, shredded"},{"qty":"for garnish","item":"cilantro and green onions"}],"steps":["Preheat oven to 375°F and cook the pasta until just shy of al dente, then drain.","In a large bowl combine pasta, chicken, salsa, tomatoes, black beans, corn, taco seasoning, and sour cream.","Stir in half the cheese and transfer to a greased 9x13 baking dish.","Top with the remaining cheese.","Bake 20-25 minutes until hot and bubbly.","Garnish with cilantro and green onions before serving."],"time":"45 min","serves":6},"fam-c-easy-enchilada-casserole":{"ingredients":[{"qty":"1 lb","item":"ground beef"},{"qty":"1","item":"onion, diced"},{"qty":"2 cans (10 oz each)","item":"enchilada sauce"},{"qty":"1 can (15 oz)","item":"black beans, drained"},{"qty":"1 cup","item":"corn kernels"},{"qty":"8","item":"corn tortillas, cut into wedges"},{"qty":"2 cups","item":"cheddar cheese, shredded"},{"qty":"1 tbsp","item":"taco seasoning"},{"qty":"for garnish","item":"sour cream and cilantro"}],"steps":["Preheat oven to 375°F.","Brown the ground beef with the onion, then drain and stir in taco seasoning, beans, and corn.","Spread a thin layer of enchilada sauce in a 9x13 dish.","Layer tortilla wedges, beef mixture, more sauce, and cheese; repeat until ingredients are used up, ending with cheese.","Bake 25-30 minutes until bubbly and golden.","Let rest 5 minutes, then garnish with sour cream and cilantro."],"time":"50 min","serves":6},"fam-c-camarones-a-la-mexicana":{"ingredients":[{"qty":"1.5 lbs","item":"shrimp, peeled and deveined"},{"qty":"3","item":"Roma tomatoes, diced"},{"qty":"1","item":"white onion, diced"},{"qty":"2","item":"serrano peppers, minced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1/4 cup","item":"cilantro, chopped"},{"qty":"1","item":"lime, juiced"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Heat olive oil in a large skillet over medium-high heat.","Saute the onion, garlic, and serrano peppers until softened.","Add the tomatoes and cook until they break down into a chunky sauce, about 5 minutes.","Add the shrimp and cook 3-4 minutes until pink and opaque.","Stir in lime juice, cilantro, salt, and pepper.","Serve hot with rice or warm tortillas."],"time":"25 min","serves":4},"fam-c-sous-vide-teriyaki-salmon-easy-freezer-m":{"ingredients":[{"qty":"4","item":"salmon fillets (6 oz each)"},{"qty":"1/4 cup","item":"soy sauce"},{"qty":"2 tbsp","item":"mirin"},{"qty":"2 tbsp","item":"brown sugar"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"toasted sesame oil"},{"qty":"for garnish","item":"sesame seeds and sliced green onion"}],"steps":["Whisk together soy sauce, mirin, brown sugar, ginger, garlic, and sesame oil to make the teriyaki marinade.","Place each salmon fillet in a freezer-safe vacuum bag with a spoonful of marinade; freeze flat until needed.","When ready to cook, set the sous vide bath to 125°F.","Cook the sealed salmon (from frozen) for 45 minutes until tender and just cooked through.","Remove from the bag and sear briefly in a hot skillet for color, if desired.","Garnish with sesame seeds and green onion before serving."],"time":"55 min","serves":4},"fam-c-shrimp-and-okra-gumbo":{"ingredients":[{"qty":"1.5 lbs","item":"shrimp, peeled and deveined"},{"qty":"1 lb","item":"okra, sliced"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2","item":"celery stalks, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"6 cups","item":"seafood or chicken stock"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"to serve","item":"cooked white rice"}],"steps":["Make a roux by cooking the oil and flour over medium heat, stirring constantly, until deep brown, about 15 minutes.","Add the onion, bell pepper, celery, and garlic and cook until softened.","Stir in the okra and cook a few minutes to reduce sliminess.","Slowly whisk in the stock, then add tomatoes and Cajun seasoning; simmer 30 minutes.","Add the shrimp and cook 5 minutes until pink and opaque.","Serve over white rice."],"time":"1 hr 10 min","serves":6},"fam-c-famous-japanese-restaurant-style-salad-d":{"ingredients":[{"qty":"1/4 cup","item":"minced onion"},{"qty":"1/4 cup","item":"peanut or vegetable oil"},{"qty":"2 tbsp","item":"rice vinegar"},{"qty":"2 tbsp","item":"water"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"1 tbsp","item":"celery, chopped"},{"qty":"1 tbsp","item":"ketchup"},{"qty":"2 tsp","item":"soy sauce"},{"qty":"1 tsp","item":"sugar"},{"qty":"1 tsp","item":"lemon juice"},{"qty":"1/2 tsp","item":"minced garlic"}],"steps":["Combine all ingredients in a blender.","Blend until smooth but still slightly textured.","Taste and adjust seasoning with more soy sauce or vinegar as needed.","Chill before serving over crisp iceberg or mixed greens."],"time":"10 min","serves":6},"fam-c-best-crunchwrap-supreme-recipe---how-to":{"ingredients":[{"qty":"1 lb","item":"ground beef"},{"qty":"1 packet","item":"taco seasoning"},{"qty":"4","item":"large flour tortillas"},{"qty":"4","item":"tostada shells"},{"qty":"1/2 cup","item":"nacho cheese sauce"},{"qty":"1 cup","item":"shredded lettuce"},{"qty":"1","item":"tomato, diced"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"1 cup","item":"shredded cheddar cheese"}],"steps":["Brown the ground beef, drain, then stir in taco seasoning with a splash of water and simmer.","Lay a large tortilla flat and spread seasoned beef in the center, then top with nacho cheese.","Place a tostada shell on top and spread with sour cream, then add lettuce, tomato, and cheddar.","Fold the edges of the tortilla up over the filling, pleating to seal into a hexagon.","Place seam-side down in a hot greased skillet and cook 2-3 minutes per side until golden and crisp.","Slice in half and serve hot."],"time":"30 min","serves":4},"fam-c-chocolate-chip-pumpkin-pound-cake-with-c":{"ingredients":[{"qty":"2.5 cups","item":"all-purpose flour"},{"qty":"1 cup","item":"pumpkin puree"},{"qty":"1 cup","item":"butter, softened"},{"qty":"2 cups","item":"granulated sugar"},{"qty":"4","item":"large eggs"},{"qty":"2 tsp","item":"pumpkin pie spice"},{"qty":"1 tsp","item":"baking powder"},{"qty":"1/2 tsp","item":"salt"},{"qty":"1 cup","item":"chocolate chips"},{"qty":"8 oz","item":"cream cheese, softened"},{"qty":"2 cups","item":"powdered sugar"},{"qty":"1 tsp","item":"ground cinnamon"}],"steps":["Preheat oven to 350°F and grease a bundt or loaf pan.","Cream the butter and granulated sugar, then beat in the eggs one at a time.","Mix in the pumpkin puree, then fold in the flour, pumpkin pie spice, baking powder, and salt.","Stir in the chocolate chips and pour the batter into the pan.","Bake 55-65 minutes until a toothpick comes out clean; cool completely.","Beat cream cheese with 1/4 cup pumpkin, powdered sugar, and cinnamon to make the frosting.","Spread the cinnamon pumpkin cream cheese frosting over the cooled cake."],"time":"1 hr 30 min","serves":10},"fam-c-roasted-pork-and-tasso-gumbo":{"ingredients":[{"qty":"1.5 lbs","item":"pork shoulder, cubed"},{"qty":"8 oz","item":"tasso ham, diced"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2","item":"celery stalks, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"8 cups","item":"chicken stock"},{"qty":"2","item":"bay leaves"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"to serve","item":"cooked white rice"}],"steps":["Roast the cubed pork shoulder at 425°F for 25 minutes until browned, then set aside.","Make a dark roux with the oil and flour, stirring constantly over medium heat about 20 minutes.","Add onion, bell pepper, celery, and garlic; cook until softened.","Stir in the tasso ham, then slowly whisk in the stock.","Add the roasted pork, bay leaves, and Cajun seasoning; simmer 1 hour until pork is tender.","Remove bay leaves and serve over white rice."],"time":"2 hr","serves":8},"fam-c-slow-cooker-harvest-beef-stew":{"ingredients":[{"qty":"2 lbs","item":"beef chuck, cubed"},{"qty":"3 tbsp","item":"all-purpose flour"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"4","item":"carrots, chopped"},{"qty":"3","item":"potatoes, cubed"},{"qty":"1","item":"butternut squash, cubed"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"4 cups","item":"beef broth"},{"qty":"2 tbsp","item":"tomato paste"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"2","item":"bay leaves"}],"steps":["Toss the beef cubes in flour, salt, and pepper, then sear in olive oil until browned.","Transfer the beef to the slow cooker along with carrots, potatoes, squash, onion, and garlic.","Stir together the beef broth, tomato paste, thyme, and bay leaves and pour over the top.","Cover and cook on low for 8 hours until the beef and vegetables are tender.","Remove bay leaves and adjust seasoning before serving."],"time":"8 hr 20 min","serves":6},"fam-c-seafood-gumbo":{"ingredients":[{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"1 lb","item":"lump crab meat"},{"qty":"1 pint","item":"shucked oysters"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2","item":"celery stalks, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"8 cups","item":"seafood stock"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"to serve","item":"cooked white rice"}],"steps":["Make a dark roux by stirring the oil and flour over medium heat until chocolate-colored, about 20 minutes.","Add onion, bell pepper, celery, and garlic; cook until softened.","Gradually whisk in the seafood stock and add Cajun seasoning; simmer 30 minutes.","Add the crab meat and simmer 10 minutes.","Add the shrimp and oysters and cook 5 minutes until shrimp are pink and oysters curl.","Serve over white rice."],"time":"1 hr 15 min","serves":8},"fam-c-panang-curry-with-chicken":{"ingredients":[{"qty":"1.5 lbs","item":"chicken thighs, sliced"},{"qty":"3 tbsp","item":"panang curry paste"},{"qty":"2 cans (13 oz each)","item":"coconut milk"},{"qty":"2 tbsp","item":"fish sauce"},{"qty":"1 tbsp","item":"brown sugar"},{"qty":"1","item":"red bell pepper, sliced"},{"qty":"5","item":"kaffir lime leaves"},{"qty":"1/4 cup","item":"Thai basil leaves"},{"qty":"2 tbsp","item":"crushed peanuts"},{"qty":"to serve","item":"jasmine rice"}],"steps":["Spoon the thick cream from the top of one can of coconut milk into a hot pan and fry the curry paste 2-3 minutes until fragrant.","Add the chicken and stir to coat in the paste.","Pour in the remaining coconut milk, fish sauce, and brown sugar; simmer 10 minutes.","Add the bell pepper and lime leaves and cook until chicken is cooked through and sauce thickens.","Stir in the Thai basil.","Serve over jasmine rice topped with crushed peanuts."],"time":"35 min","serves":4},"fam-c-easy-to-make-italian-pasta-salad":{"ingredients":[{"qty":"1 lb","item":"rotini pasta"},{"qty":"1 cup","item":"cherry tomatoes, halved"},{"qty":"1","item":"cucumber, diced"},{"qty":"1/2 cup","item":"black olives, sliced"},{"qty":"1/2 cup","item":"red onion, diced"},{"qty":"8 oz","item":"mozzarella pearls"},{"qty":"4 oz","item":"salami, diced"},{"qty":"1 cup","item":"Italian dressing"},{"qty":"1/4 cup","item":"grated Parmesan"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the pasta until al dente, drain, and rinse under cold water.","In a large bowl combine the pasta, tomatoes, cucumber, olives, red onion, mozzarella, and salami.","Pour the Italian dressing over the top and toss to coat.","Stir in the Parmesan and season with salt and pepper.","Chill at least 1 hour before serving."],"time":"20 min","serves":8},"fam-c-clean-skinny-kettle-corn":{"ingredients":[{"qty":"1/2 cup","item":"popcorn kernels"},{"qty":"2 tbsp","item":"coconut oil"},{"qty":"3 tbsp","item":"coconut sugar"},{"qty":"1/2 tsp","item":"sea salt"}],"steps":["Heat the coconut oil in a large heavy pot over medium-high heat with a couple of test kernels.","When the test kernels pop, add the rest of the kernels and the coconut sugar, then cover.","Shake the pot continuously to keep the sugar from burning as the corn pops.","Once popping slows to a few seconds between pops, remove from heat.","Pour into a bowl, sprinkle with sea salt, and toss to coat."],"time":"10 min","serves":4},"fam-c-creamy-butter-chicken":{"ingredients":[{"qty":"1.5 lbs","item":"chicken thighs, cubed"},{"qty":"1 cup","item":"plain yogurt"},{"qty":"2 tbsp","item":"garam masala"},{"qty":"4 tbsp","item":"butter"},{"qty":"1","item":"onion, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"1 can (14 oz)","item":"crushed tomatoes"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"paprika"},{"qty":"to serve","item":"basmati rice and naan"}],"steps":["Marinate the chicken in yogurt and 1 tbsp garam masala for at least 30 minutes.","Melt the butter and saute the onion, garlic, and ginger until soft.","Stir in cumin, paprika, and remaining garam masala, then add the crushed tomatoes and simmer 10 minutes.","Add the marinated chicken and cook until cooked through, about 12 minutes.","Stir in the heavy cream and simmer gently 5 minutes until rich and creamy.","Serve with basmati rice and warm naan."],"time":"50 min","serves":4},"fam-c-smash-burgers":{"ingredients":[{"qty":"1.5 lbs","item":"ground beef (80/20)"},{"qty":"4","item":"burger buns"},{"qty":"4 slices","item":"American cheese"},{"qty":"1","item":"onion, thinly sliced"},{"qty":"2 tbsp","item":"butter"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"pickles, lettuce, and burger sauce"}],"steps":["Divide the beef into 4 loose balls without overworking the meat.","Heat a cast iron skillet or griddle until very hot.","Place a beef ball on the griddle and smash flat with a spatula; season with salt and pepper.","Cook 2 minutes until a deep crust forms, then flip and top with cheese.","Cook 1 more minute until the cheese melts.","Toast the buttered buns and build burgers with the patty, onion, pickles, lettuce, and burger sauce."],"time":"20 min","serves":4},"fam-c-grilled-salmon-with-herb-and-meyer-lemon":{"ingredients":[{"qty":"4","item":"salmon fillets (6 oz each)"},{"qty":"6 tbsp","item":"butter, softened"},{"qty":"2 tbsp","item":"fresh dill, chopped"},{"qty":"2 tbsp","item":"fresh parsley, chopped"},{"qty":"1","item":"Meyer lemon, zested and juiced"},{"qty":"1 clove","item":"garlic, minced"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Mash the softened butter with the dill, parsley, Meyer lemon zest, garlic, and a pinch of salt, then roll into a log and chill.","Preheat the grill to medium-high and oil the grates.","Brush the salmon with olive oil, Meyer lemon juice, salt, and pepper.","Grill skin-side down 4-5 minutes, then flip and cook 2-3 more minutes until just opaque.","Top each fillet with a slice of the herb and Meyer lemon compound butter so it melts over the fish."],"time":"25 min","serves":4},"fam-c-homemade-chicken-pot-pie":{"ingredients":[{"qty":"1 lb","item":"cooked chicken, diced"},{"qty":"4 tbsp","item":"butter"},{"qty":"1","item":"onion, diced"},{"qty":"2","item":"carrots, diced"},{"qty":"2","item":"celery stalks, diced"},{"qty":"1 cup","item":"frozen peas"},{"qty":"1/3 cup","item":"all-purpose flour"},{"qty":"2 cups","item":"chicken broth"},{"qty":"1 cup","item":"milk"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"2","item":"pie crusts"},{"qty":"1","item":"egg, beaten"}],"steps":["Preheat oven to 400°F.","Melt the butter and saute the onion, carrots, and celery until softened.","Sprinkle in the flour and cook 1 minute, then gradually whisk in the broth and milk until thickened.","Stir in the chicken, peas, and thyme; season with salt and pepper.","Line a pie dish with one crust, add the filling, and top with the second crust, crimping the edges and cutting vents.","Brush with beaten egg and bake 35-40 minutes until golden brown.","Let rest 10 minutes before serving."],"time":"1 hr 10 min","serves":6},"fam-c-best-cheesy-chicken-alfredo-soup---how-t":{"ingredients":[{"qty":"1 lb","item":"cooked chicken, shredded"},{"qty":"8 oz","item":"fettuccine, broken into pieces"},{"qty":"4 tbsp","item":"butter"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1/4 cup","item":"all-purpose flour"},{"qty":"4 cups","item":"chicken broth"},{"qty":"2 cups","item":"heavy cream"},{"qty":"1.5 cups","item":"Parmesan cheese, grated"},{"qty":"1 cup","item":"mozzarella cheese, shredded"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Melt the butter in a large pot and saute the garlic until fragrant.","Whisk in the flour and cook 1 minute, then gradually add the chicken broth.","Stir in the heavy cream and bring to a gentle simmer.","Add the broken fettuccine and cook until tender, about 10 minutes.","Stir in the shredded chicken, Parmesan, and mozzarella until melted and creamy.","Season with salt and pepper and serve hot."],"time":"35 min","serves":6},"fam-c-creamy-lemon-zucchini-pasta":{"ingredients":[{"qty":"12 oz","item":"spaghetti"},{"qty":"3","item":"zucchini, sliced into half-moons"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1","item":"lemon, zested and juiced"},{"qty":"3/4 cup","item":"heavy cream"},{"qty":"1/2 cup","item":"Parmesan cheese, grated"},{"qty":"1/4 cup","item":"fresh basil, torn"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the spaghetti until al dente, reserving 1/2 cup pasta water before draining.","Saute the zucchini in olive oil over medium-high heat until lightly golden, then add the garlic.","Pour in the heavy cream, lemon zest, and lemon juice; simmer 2 minutes.","Add the pasta and Parmesan, tossing with a splash of pasta water until creamy.","Stir in the basil and season with salt and pepper before serving."],"time":"25 min","serves":4},"fam-c-slow-cooker-chicken-chili":{"ingredients":[{"qty":"1.5 lbs","item":"boneless chicken breasts"},{"qty":"2 cans (15 oz each)","item":"white beans, drained"},{"qty":"1 can (15 oz)","item":"corn, drained"},{"qty":"2 cans (4 oz each)","item":"diced green chiles"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"4 cups","item":"chicken broth"},{"qty":"2 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"for garnish","item":"cilantro, lime, and shredded cheese"}],"steps":["Place the chicken, beans, corn, green chiles, onion, garlic, broth, cumin, and oregano in the slow cooker.","Cover and cook on low for 6 hours.","Remove the chicken, shred it, and return it to the pot.","Stir in the sour cream until creamy.","Serve topped with cilantro, a squeeze of lime, and shredded cheese."],"time":"6 hr 15 min","serves":6},"fam-c-chocolate-lasagna":{"ingredients":[{"qty":"36","item":"Oreo cookies, crushed"},{"qty":"6 tbsp","item":"butter, melted"},{"qty":"8 oz","item":"cream cheese, softened"},{"qty":"1/4 cup","item":"granulated sugar"},{"qty":"12 oz","item":"whipped topping, divided"},{"qty":"2 packages (3.9 oz each)","item":"instant chocolate pudding mix"},{"qty":"3 cups","item":"cold milk"},{"qty":"1/2 cup","item":"mini chocolate chips"}],"steps":["Mix the crushed Oreos with melted butter and press into the bottom of a 9x13 dish; chill.","Beat the cream cheese with the sugar, then fold in 1.5 cups of whipped topping and spread over the crust.","Whisk the pudding mix with cold milk until thick, then spread over the cream cheese layer.","Spread the remaining whipped topping on top.","Sprinkle with mini chocolate chips.","Refrigerate at least 4 hours before slicing and serving."],"time":"4 hr 30 min","serves":12},"fam-c-camarones-al-mojo-de-ajo-garlic-shrimp-w":{"ingredients":[{"qty":"1.5 lbs","item":"shrimp, peeled and deveined"},{"qty":"12 oz","item":"linguine or spaghetti"},{"qty":"10 cloves","item":"garlic, thinly sliced"},{"qty":"1/3 cup","item":"olive oil"},{"qty":"3 tbsp","item":"butter"},{"qty":"1/4 tsp","item":"red pepper flakes"},{"qty":"2 tbsp","item":"lime juice"},{"qty":"1/4 cup","item":"fresh parsley, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the pasta until al dente, reserving some pasta water before draining.","Gently heat the olive oil and butter with the sliced garlic over low heat until golden and fragrant, being careful not to burn it.","Add the red pepper flakes and shrimp; cook 3-4 minutes until pink.","Stir in the lime juice and a splash of pasta water.","Toss in the drained pasta and parsley until coated.","Season with salt and pepper and serve immediately."],"time":"25 min","serves":4},"fam-c-instant-pot-chicken-pho":{"ingredients":[{"qty":"2 lbs","item":"bone-in chicken thighs"},{"qty":"1","item":"onion, halved"},{"qty":"3-inch piece","item":"fresh ginger, halved"},{"qty":"3","item":"star anise pods"},{"qty":"1","item":"cinnamon stick"},{"qty":"3","item":"whole cloves"},{"qty":"8 cups","item":"water"},{"qty":"2 tbsp","item":"fish sauce"},{"qty":"14 oz","item":"rice noodles"},{"qty":"for serving","item":"bean sprouts, Thai basil, lime, and sliced jalapeño"}],"steps":["Char the onion and ginger under the broiler or in the Instant Pot on saute for deeper flavor.","Add the chicken, charred aromatics, star anise, cinnamon, cloves, water, and fish sauce to the Instant Pot.","Seal and cook on high pressure for 20 minutes, then allow a natural release.","Remove the chicken, shred it, and strain the broth.","Soak or cook the rice noodles according to package directions and divide among bowls.","Top with shredded chicken and ladle the hot broth over, then serve with bean sprouts, basil, lime, and jalapeño."],"time":"50 min","serves":4},"fam-c-creamless-fettuccine-alfredo-with-califo":{"ingredients":[{"qty":"12 oz","item":"fettuccine"},{"qty":"2","item":"ripe California avocados"},{"qty":"3 cloves","item":"garlic"},{"qty":"1/2 cup","item":"grated Parmesan cheese"},{"qty":"2 tbsp","item":"lemon juice"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1/4 cup","item":"fresh basil"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the fettuccine until al dente, reserving 1 cup pasta water before draining.","Blend the avocados, garlic, Parmesan, lemon juice, olive oil, and basil into a smooth sauce.","Thin the sauce with a little pasta water to reach a creamy consistency.","Toss the hot pasta with the avocado sauce, adding more pasta water as needed.","Season with salt and pepper and serve immediately."],"time":"20 min","serves":4},"fam-c-mediterranean-flatbread":{"ingredients":[{"qty":"2","item":"flatbreads or naan"},{"qty":"1/2 cup","item":"hummus"},{"qty":"1 cup","item":"cherry tomatoes, halved"},{"qty":"1/2","item":"cucumber, diced"},{"qty":"1/3 cup","item":"kalamata olives, sliced"},{"qty":"1/2 cup","item":"feta cheese, crumbled"},{"qty":"1/4","item":"red onion, thinly sliced"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Preheat oven to 400°F and place the flatbreads on a baking sheet.","Brush each flatbread with olive oil and bake 5 minutes until lightly crisp.","Spread a layer of hummus over each warm flatbread.","Top with cherry tomatoes, cucumber, olives, feta, and red onion.","Drizzle with olive oil and sprinkle with parsley before slicing and serving."],"time":"15 min","serves":2},"fam-c-barbecue-pulled-pork-shepherds-pie---eas":{"ingredients":[{"qty":"3 cups","item":"cooked pulled pork"},{"qty":"1 cup","item":"barbecue sauce"},{"qty":"1 cup","item":"frozen corn"},{"qty":"1","item":"small onion, diced"},{"qty":"2.5 lbs","item":"potatoes, peeled and cubed"},{"qty":"4 tbsp","item":"butter"},{"qty":"1/2 cup","item":"milk"},{"qty":"1 cup","item":"cheddar cheese, shredded"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 375°F.","Boil the potatoes until tender, then mash with butter, milk, salt, and pepper.","Saute the onion until soft, then stir in the pulled pork, barbecue sauce, and corn.","Spread the barbecue pork mixture in the bottom of a baking dish.","Spread the mashed potatoes over the top and sprinkle with cheddar cheese.","Bake 25-30 minutes until golden and bubbly."],"time":"55 min","serves":6},"fam-c-cream-cheese-sugar-cookies":{"ingredients":[{"qty":"1 cup","item":"unsalted butter, softened"},{"qty":"4 oz","item":"cream cheese, softened"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1","item":"large egg"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1/2 tsp","item":"almond extract"},{"qty":"2 3/4 cups","item":"all-purpose flour"},{"qty":"1 tsp","item":"baking powder"},{"qty":"1/2 tsp","item":"salt"}],"steps":["Beat the butter, cream cheese, and sugar together until light and fluffy, about 3 minutes.","Mix in the egg, vanilla, and almond extract until combined.","Whisk the flour, baking powder, and salt together, then gradually beat into the wet ingredients to form a soft dough.","Chill the dough for 1 hour. Preheat oven to 350F and line baking sheets with parchment.","Roll dough into 1-inch balls (or roll out and cut shapes), spacing them on the sheets.","Bake 10 to 12 minutes until set but not browned. Cool on the sheet 5 minutes before transferring to a rack."],"time":"1 hr 30 min","serves":24},"fam-c-chocolate-eclair-cake":{"ingredients":[{"qty":"1 box","item":"graham crackers"},{"qty":"2 (3.4 oz) boxes","item":"instant vanilla pudding mix"},{"qty":"3 cups","item":"cold milk"},{"qty":"8 oz","item":"whipped topping, thawed"},{"qty":"1 cup","item":"semisweet chocolate chips"},{"qty":"1/2 cup","item":"heavy cream"},{"qty":"2 tbsp","item":"unsalted butter"},{"qty":"1 tsp","item":"vanilla extract"}],"steps":["Whisk the pudding mix with cold milk for 2 minutes, then fold in the whipped topping.","Line the bottom of a 9x13 dish with a single layer of graham crackers.","Spread half the pudding mixture over the crackers, add another cracker layer, then the remaining pudding and a final cracker layer.","Heat the cream and butter until steaming, pour over the chocolate chips, let sit 2 minutes, then stir with the vanilla until smooth.","Pour the ganache over the top cracker layer and spread evenly.","Cover and refrigerate at least 4 hours, preferably overnight, so the crackers soften into cake."],"time":"4 hr 20 min","serves":12},"fam-c-creamy-garlic-butter-chicken-linguine-in":{"ingredients":[{"qty":"12 oz","item":"linguine"},{"qty":"2","item":"boneless skinless chicken breasts"},{"qty":"3 tbsp","item":"butter"},{"qty":"5 cloves","item":"garlic, minced"},{"qty":"1 1/2 cups","item":"heavy cream"},{"qty":"1 cup","item":"grated Parmesan"},{"qty":"1/2 cup","item":"chicken broth"},{"qty":"1 tbsp","item":"olive oil"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Cook the linguine in salted water until al dente, reserving 1/2 cup pasta water, then drain.","Season the chicken with salt and pepper and sear in olive oil over medium-high until golden and cooked through, about 6 minutes per side. Rest, then slice.","Melt the butter in the same pan and saute the garlic for 1 minute until fragrant.","Pour in the broth and cream, simmer 3 minutes, then whisk in the Parmesan until smooth.","Toss the linguine in the sauce, loosening with pasta water as needed.","Top with sliced chicken and parsley, and serve hot."],"time":"35 min","serves":4},"fam-c-easy-chicken-and-andouille-gumbo":{"ingredients":[{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"1 1/2 lb","item":"boneless chicken thighs, cubed"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"6 cups","item":"chicken broth"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"2","item":"bay leaves"},{"qty":"3 cups","item":"cooked white rice"}],"steps":["Make a roux by stirring the oil and flour over medium heat until it reaches a deep brown peanut-butter color, about 20 minutes.","Add the onion, bell pepper, and celery and cook 5 minutes until softened, then stir in the garlic.","Slowly whisk in the broth, then add the Cajun seasoning and bay leaves.","Add the andouille and chicken, bring to a boil, then reduce and simmer 45 minutes.","Skim any fat, discard the bay leaves, and adjust seasoning.","Ladle over scoops of white rice to serve."],"time":"1 hr 30 min","serves":6},"fam-c-one-pot-creamy-cajun-sausage-pasta":{"ingredients":[{"qty":"1 lb","item":"smoked sausage, sliced"},{"qty":"12 oz","item":"penne pasta"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"red bell pepper, sliced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"Cajun seasoning"},{"qty":"1 (14.5 oz) can","item":"diced tomatoes"},{"qty":"3 cups","item":"chicken broth"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1 cup","item":"shredded cheddar"},{"qty":"1 tbsp","item":"olive oil"}],"steps":["Brown the sausage in olive oil in a large pot, then set aside.","Saute the onion and bell pepper until soft, then add the garlic and Cajun seasoning.","Stir in the diced tomatoes, broth, cream, and uncooked penne.","Bring to a boil, then cover and simmer 12 to 15 minutes, stirring occasionally, until the pasta is tender.","Return the sausage to the pot and stir in the cheddar until melted and creamy.","Rest 5 minutes to thicken, then serve."],"time":"35 min","serves":4},"fam-c-chicken-and-sweet-potato-bowl":{"ingredients":[{"qty":"1 lb","item":"boneless chicken breast, cubed"},{"qty":"2","item":"sweet potatoes, peeled and diced"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"garlic powder"},{"qty":"2 cups","item":"cooked quinoa or rice"},{"qty":"2 cups","item":"baby spinach"},{"qty":"1","item":"avocado, sliced"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 425F. Toss the sweet potatoes with 1 tbsp oil, half the spices, and salt, then roast 25 minutes until tender.","Toss the chicken with the remaining spices and salt.","Sear the chicken in 1 tbsp oil over medium-high until golden and cooked through, about 8 minutes.","Divide the quinoa among bowls and top with spinach.","Add the roasted sweet potatoes and chicken.","Finish with avocado slices and a drizzle of olive oil."],"time":"40 min","serves":4},"fam-c-copycat-panda-expressTM-orange-chicken":{"ingredients":[{"qty":"1 1/2 lb","item":"boneless chicken thighs, cubed"},{"qty":"1","item":"egg, beaten"},{"qty":"1/2 cup","item":"cornstarch"},{"qty":"1/4 cup","item":"flour"},{"qty":"3 cups","item":"vegetable oil, for frying"},{"qty":"1/2 cup","item":"orange juice"},{"qty":"1/4 cup","item":"sugar"},{"qty":"3 tbsp","item":"soy sauce"},{"qty":"3 tbsp","item":"rice vinegar"},{"qty":"1 tbsp","item":"grated ginger"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"cornstarch mixed with 2 tbsp water"}],"steps":["Toss the chicken with the egg, then dredge in the cornstarch and flour mix.","Heat oil to 350F and fry the chicken in batches until golden and crisp, about 4 minutes. Drain.","In a clean pan, simmer the orange juice, sugar, soy sauce, vinegar, ginger, and garlic for 2 minutes.","Stir in the cornstarch slurry and cook until the sauce is thick and glossy.","Toss the fried chicken in the sauce to coat.","Serve immediately over steamed rice."],"time":"40 min","serves":4},"fam-c-healthy-pumpkin-baked-oatmeal":{"ingredients":[{"qty":"2 cups","item":"rolled oats"},{"qty":"1 cup","item":"pumpkin puree"},{"qty":"1 3/4 cups","item":"milk of choice"},{"qty":"1/3 cup","item":"maple syrup"},{"qty":"2","item":"eggs"},{"qty":"1 tsp","item":"baking powder"},{"qty":"2 tsp","item":"pumpkin pie spice"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1/2 tsp","item":"salt"},{"qty":"1/2 cup","item":"chopped pecans"}],"steps":["Preheat oven to 350F and grease an 8x8 baking dish.","Whisk the pumpkin, milk, maple syrup, eggs, and vanilla together.","Stir in the oats, baking powder, pumpkin pie spice, and salt.","Pour into the dish and scatter the pecans over the top.","Bake 40 to 45 minutes until set and the edges are golden.","Cool 10 minutes and serve warm."],"time":"55 min","serves":6},"fam-c-the-fully-loaded-iceberg-wedge-salad":{"ingredients":[{"qty":"1","item":"head iceberg lettuce, quartered"},{"qty":"6 slices","item":"bacon, cooked and crumbled"},{"qty":"1/2 cup","item":"crumbled blue cheese"},{"qty":"1 cup","item":"cherry tomatoes, halved"},{"qty":"1/4","item":"red onion, thinly sliced"},{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"1/4 cup","item":"sour cream"},{"qty":"2 tbsp","item":"buttermilk"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"2 tbsp","item":"chopped chives"}],"steps":["Whisk the mayonnaise, sour cream, buttermilk, lemon juice, and half the blue cheese into a dressing. Season with salt and pepper.","Place each iceberg wedge on a plate.","Spoon the blue cheese dressing generously over each wedge.","Scatter the bacon, tomatoes, and red onion over the top.","Finish with the remaining blue cheese crumbles and chives."],"time":"15 min","serves":4},"fam-c-cowgirl-caviar":{"ingredients":[{"qty":"1 (15 oz) can","item":"black-eyed peas, drained"},{"qty":"1 (15 oz) can","item":"black beans, drained and rinsed"},{"qty":"1 1/2 cups","item":"corn kernels"},{"qty":"1","item":"red bell pepper, diced"},{"qty":"1","item":"jalapeno, minced"},{"qty":"1/2","item":"red onion, diced"},{"qty":"1/2 cup","item":"chopped cilantro"},{"qty":"1/3 cup","item":"olive oil"},{"qty":"1/4 cup","item":"lime juice"},{"qty":"2 tbsp","item":"red wine vinegar"},{"qty":"1 tsp","item":"ground cumin"}],"steps":["Combine the black-eyed peas, black beans, corn, bell pepper, jalapeno, red onion, and cilantro in a large bowl.","Whisk the olive oil, lime juice, vinegar, and cumin together with salt and pepper.","Pour the dressing over the bean mixture and toss to coat.","Cover and chill at least 1 hour to let the flavors meld.","Stir again and serve with tortilla chips."],"time":"1 hr 15 min","serves":8},"fam-c-tortas-fritas":{"ingredients":[{"qty":"3 cups","item":"all-purpose flour"},{"qty":"1 tbsp","item":"baking powder"},{"qty":"1 tsp","item":"salt"},{"qty":"3 tbsp","item":"lard or butter, melted"},{"qty":"1 cup","item":"warm water or milk"},{"qty":"4 cups","item":"oil, for frying"},{"qty":"1/4 cup","item":"sugar, for dusting"}],"steps":["Whisk the flour, baking powder, and salt together in a bowl.","Stir in the melted lard and gradually add warm water until a soft dough forms.","Knead briefly, cover, and rest 20 minutes.","Divide into 8 balls and roll each into a thin round, poking a hole in the center.","Heat the oil to 350F and fry each torta until puffed and golden, about 1 minute per side.","Drain on paper towels and dust with sugar while warm."],"time":"45 min","serves":8},"fam-c-one-pot-garlic-parmesan-pasta":{"ingredients":[{"qty":"12 oz","item":"spaghetti"},{"qty":"4 tbsp","item":"butter"},{"qty":"6 cloves","item":"garlic, minced"},{"qty":"3 cups","item":"chicken or vegetable broth"},{"qty":"1 cup","item":"milk"},{"qty":"1 cup","item":"grated Parmesan"},{"qty":"1/2 tsp","item":"Italian seasoning"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Melt the butter in a large pot and saute the garlic for 1 minute until fragrant.","Add the broth, milk, Italian seasoning, and spaghetti.","Bring to a boil, then simmer uncovered, stirring often, until the pasta is tender and the liquid has reduced, about 12 minutes.","Stir in the Parmesan until the sauce is creamy.","Season with salt and pepper and garnish with parsley."],"time":"25 min","serves":4},"fam-c-air-fryer-greek-chicken-and-veggies":{"ingredients":[{"qty":"1 1/2 lb","item":"boneless chicken breast, cubed"},{"qty":"1","item":"zucchini, sliced"},{"qty":"1","item":"red bell pepper, chunked"},{"qty":"1","item":"red onion, chunked"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"2 tbsp","item":"lemon juice"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"dried oregano"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 cup","item":"crumbled feta"}],"steps":["Whisk the olive oil, lemon juice, garlic, oregano, and salt into a marinade.","Toss the chicken and vegetables in the marinade and let sit 15 minutes.","Preheat the air fryer to 380F.","Add the chicken and veggies to the basket in a single layer and cook 14 to 16 minutes, shaking halfway, until the chicken is cooked through.","Transfer to a platter and top with crumbled feta."],"time":"35 min","serves":4},"fam-c-black-pepper-chicken-curry":{"ingredients":[{"qty":"1 1/2 lb","item":"boneless chicken thighs, cubed"},{"qty":"2 tbsp","item":"coarsely ground black pepper"},{"qty":"2 tbsp","item":"oil"},{"qty":"1","item":"large onion, sliced"},{"qty":"1 tbsp","item":"grated ginger"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"2","item":"tomatoes, chopped"},{"qty":"1 tsp","item":"ground turmeric"},{"qty":"1 tsp","item":"ground coriander"},{"qty":"1 cup","item":"coconut milk"},{"qty":"1 tsp","item":"salt"},{"qty":"2 tbsp","item":"chopped cilantro"}],"steps":["Heat the oil and saute the onion until golden, about 8 minutes.","Add the ginger and garlic and cook 1 minute, then stir in the turmeric, coriander, and black pepper.","Add the tomatoes and cook until they break down into a paste.","Add the chicken and salt, searing for a few minutes, then pour in the coconut milk.","Simmer covered 20 minutes until the chicken is tender and the sauce thickens.","Garnish with cilantro and serve with rice."],"time":"45 min","serves":4},"fam-c-chicken-sauce-piquante":{"ingredients":[{"qty":"1/3 cup","item":"vegetable oil"},{"qty":"1/3 cup","item":"all-purpose flour"},{"qty":"2 lb","item":"chicken thighs"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 (14.5 oz) can","item":"diced tomatoes"},{"qty":"2 cups","item":"chicken broth"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"1/4 tsp","item":"cayenne pepper"},{"qty":"3 cups","item":"cooked rice"}],"steps":["Make a medium-brown roux by cooking the oil and flour over medium heat, stirring constantly, about 15 minutes.","Add the onion, bell pepper, and celery and cook until softened, then add the garlic.","Stir in the tomatoes, broth, Cajun seasoning, and cayenne.","Add the chicken thighs, bring to a simmer, then cover and cook 45 minutes until tender.","Adjust seasoning and let the sauce thicken uncovered for 10 minutes.","Serve over rice."],"time":"1 hr 20 min","serves":6},"fam-c-baked-bbq-ribs-with-dry-rub-bbq-sauce":{"ingredients":[{"qty":"2 racks","item":"baby back ribs"},{"qty":"3 tbsp","item":"brown sugar"},{"qty":"1 tbsp","item":"smoked paprika"},{"qty":"1 tbsp","item":"garlic powder"},{"qty":"1 tsp","item":"onion powder"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"2 tsp","item":"salt"},{"qty":"1 tsp","item":"black pepper"},{"qty":"1 1/2 cups","item":"BBQ sauce"}],"steps":["Preheat oven to 300F. Remove the membrane from the back of the ribs.","Combine the brown sugar, paprika, garlic powder, onion powder, cumin, salt, and pepper into a dry rub.","Coat the ribs all over with the rub, then wrap tightly in foil.","Bake on a sheet pan for 2 1/2 hours until tender.","Unwrap, brush generously with BBQ sauce, and broil 5 minutes until caramelized.","Rest 10 minutes, then slice between the bones."],"time":"3 hr","serves":6},"fam-c-strawberry-spinach-salad-i":{"ingredients":[{"qty":"6 cups","item":"baby spinach"},{"qty":"2 cups","item":"strawberries, sliced"},{"qty":"1/2 cup","item":"sliced almonds, toasted"},{"qty":"1/4","item":"red onion, thinly sliced"},{"qty":"1/3 cup","item":"crumbled feta"},{"qty":"1/4 cup","item":"olive oil"},{"qty":"2 tbsp","item":"balsamic vinegar"},{"qty":"1 tbsp","item":"honey"},{"qty":"1 tsp","item":"Dijon mustard"}],"steps":["Whisk the olive oil, balsamic vinegar, honey, and Dijon into a dressing with a pinch of salt.","Combine the spinach, strawberries, almonds, and red onion in a large bowl.","Drizzle the dressing over the salad and toss gently.","Top with crumbled feta and serve immediately."],"time":"15 min","serves":4},"fam-c-instant-pot-mushroom-risotto":{"ingredients":[{"qty":"1 1/2 cups","item":"Arborio rice"},{"qty":"8 oz","item":"cremini mushrooms, sliced"},{"qty":"3 tbsp","item":"butter"},{"qty":"1","item":"shallot, minced"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1/2 cup","item":"white wine"},{"qty":"4 cups","item":"chicken or vegetable broth"},{"qty":"3/4 cup","item":"grated Parmesan"},{"qty":"to taste","item":"salt and pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Set the Instant Pot to saute and melt 2 tbsp butter. Cook the mushrooms until browned, then set aside.","Saute the shallot and garlic in the remaining butter until soft.","Add the rice and toast for 1 minute, then pour in the wine and let it absorb.","Add the broth, seal the lid, and cook on high pressure for 6 minutes.","Quick-release the pressure, then stir in the mushrooms, Parmesan, and parsley.","Season to taste and serve immediately."],"time":"30 min","serves":4},"fam-c-slow-cooker-chicken-chipotle-sandwiches":{"ingredients":[{"qty":"2 lb","item":"boneless chicken thighs"},{"qty":"2","item":"chipotle peppers in adobo, minced"},{"qty":"2 tbsp","item":"adobo sauce"},{"qty":"1","item":"onion, sliced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"tomato sauce"},{"qty":"1 tbsp","item":"brown sugar"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"salt"},{"qty":"6","item":"sandwich buns"}],"steps":["Place the chicken, onion, and garlic in the slow cooker.","Stir together the chipotle, adobo sauce, tomato sauce, brown sugar, cumin, and salt, then pour over the chicken.","Cover and cook on low for 6 hours or high for 3 hours.","Shred the chicken with two forks and stir it back into the sauce.","Pile the saucy chicken onto buns and serve."],"time":"6 hr 15 min","serves":6},"fam-c-best-bacon-cheddar-waffles-recipe-how-to":{"ingredients":[{"qty":"2 cups","item":"all-purpose flour"},{"qty":"1 tbsp","item":"baking powder"},{"qty":"1 tbsp","item":"sugar"},{"qty":"1/2 tsp","item":"salt"},{"qty":"2","item":"eggs"},{"qty":"1 3/4 cups","item":"milk"},{"qty":"1/3 cup","item":"melted butter"},{"qty":"1 cup","item":"shredded sharp cheddar"},{"qty":"6 slices","item":"bacon, cooked and crumbled"}],"steps":["Preheat the waffle iron.","Whisk the flour, baking powder, sugar, and salt together.","In another bowl, whisk the eggs, milk, and melted butter.","Stir the wet into the dry until just combined, then fold in the cheddar and bacon.","Pour batter into the waffle iron and cook until golden and crisp.","Serve hot with maple syrup."],"time":"25 min","serves":4},"fam-c-italian-baked-chicken-thighs":{"ingredients":[{"qty":"8","item":"bone-in chicken thighs"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"Italian seasoning"},{"qty":"1 tsp","item":"garlic powder"},{"qty":"1 tsp","item":"paprika"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"1/4 cup","item":"grated Parmesan"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Preheat oven to 425F.","Combine the olive oil, garlic, Italian seasoning, garlic powder, paprika, salt, and pepper.","Coat the chicken thighs all over with the mixture and arrange skin-side up in a baking dish.","Sprinkle the Parmesan over the top.","Bake 35 to 40 minutes until the skin is crisp and the internal temperature reaches 175F.","Garnish with parsley and serve."],"time":"45 min","serves":4},"fam-c-copycat-olive-gardenTM-chicken-alfredo":{"ingredients":[{"qty":"12 oz","item":"fettuccine"},{"qty":"2","item":"boneless chicken breasts"},{"qty":"1/2 cup","item":"butter"},{"qty":"2 cups","item":"heavy cream"},{"qty":"1 1/2 cups","item":"grated Parmesan"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"olive oil"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Cook the fettuccine in salted water until al dente, then drain.","Season the chicken and sear in olive oil until golden and cooked through, about 6 minutes per side. Rest, then slice.","Melt the butter in a saucepan and saute the garlic for 1 minute.","Add the cream and bring to a gentle simmer, then whisk in the Parmesan until smooth and thick.","Toss the fettuccine in the sauce and season with salt and pepper.","Top with sliced chicken and parsley to serve."],"time":"35 min","serves":4},"fam-c-salsa-de-mesa-table-salsa":{"ingredients":[{"qty":"6","item":"Roma tomatoes"},{"qty":"2","item":"jalapenos"},{"qty":"1/2","item":"white onion"},{"qty":"2 cloves","item":"garlic"},{"qty":"1/3 cup","item":"chopped cilantro"},{"qty":"2 tbsp","item":"lime juice"},{"qty":"1 tsp","item":"salt"}],"steps":["Char the tomatoes and jalapenos under a broiler or in a dry skillet until blistered.","Add the charred vegetables, onion, and garlic to a blender.","Add the cilantro, lime juice, and salt.","Pulse to your preferred texture, from chunky to smooth.","Taste and adjust the salt and lime, then chill before serving."],"time":"20 min","serves":6},"fam-c-fish-tacos-with-broccoli-slaw":{"ingredients":[{"qty":"1 lb","item":"white fish fillets (cod or tilapia)"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1 tbsp","item":"chili powder"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"3 cups","item":"broccoli slaw mix"},{"qty":"1/4 cup","item":"mayonnaise"},{"qty":"2 tbsp","item":"lime juice"},{"qty":"1 tbsp","item":"honey"},{"qty":"8","item":"small corn tortillas"},{"qty":"1/4 cup","item":"chopped cilantro"}],"steps":["Whisk the mayonnaise, lime juice, and honey together, then toss with the broccoli slaw and cilantro. Chill.","Rub the fish with olive oil, chili powder, cumin, and salt.","Sear the fish over medium-high heat 3 to 4 minutes per side until it flakes, then break into pieces.","Warm the tortillas in a dry skillet.","Fill each tortilla with fish and a pile of broccoli slaw.","Serve with lime wedges."],"time":"25 min","serves":4},"fam-c-shrimp-etouffee":{"ingredients":[{"qty":"1/2 cup","item":"butter"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"3 cups","item":"seafood or chicken stock"},{"qty":"1 1/2 lb","item":"shrimp, peeled and deveined"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"3","item":"green onions, sliced"},{"qty":"3 cups","item":"cooked white rice"}],"steps":["Melt the butter and whisk in the flour, cooking over medium heat to a blond-to-light-brown roux, about 10 minutes.","Add the onion, bell pepper, and celery and cook until soft, then stir in the garlic.","Gradually whisk in the stock and Cajun seasoning, then simmer 15 minutes until thickened.","Add the shrimp and cook 4 to 5 minutes until pink and curled.","Stir in the green onions and adjust seasoning.","Serve over white rice."],"time":"40 min","serves":4},"fam-c-slow-cooker-chicken-alfredo-tortellini":{"ingredients":[{"qty":"1 1/2 lb","item":"boneless chicken breast"},{"qty":"1 (15 oz) jar","item":"Alfredo sauce"},{"qty":"1 cup","item":"chicken broth"},{"qty":"20 oz","item":"refrigerated cheese tortellini"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1 cup","item":"grated Parmesan"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"2 cups","item":"fresh spinach"}],"steps":["Place the chicken in the slow cooker with the Alfredo sauce, broth, garlic, and Italian seasoning.","Cover and cook on low for 5 hours until the chicken is tender.","Remove and shred the chicken, then return it to the pot.","Stir in the tortellini, cream, and Parmesan, then cover and cook on high 20 to 30 minutes until the tortellini is tender.","Stir in the spinach until wilted and serve."],"time":"5 hr 30 min","serves":6},"fam-c-easy-roasted-parmesan-pesto-potatoes":{"ingredients":[{"qty":"2 lb","item":"baby potatoes, halved"},{"qty":"3 tbsp","item":"basil pesto"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"1 tsp","item":"garlic powder"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Preheat oven to 425F and line a sheet pan with parchment.","Toss the potatoes with the pesto, olive oil, garlic powder, salt, and pepper.","Spread cut-side down in a single layer on the pan.","Roast 25 minutes, then sprinkle with Parmesan and roast 5 to 8 minutes more until crisp and golden.","Garnish with parsley and serve."],"time":"40 min","serves":4},"fam-c-chicken-sauce-piquante-2":{"ingredients":[{"qty":"1/3 cup","item":"vegetable oil"},{"qty":"1/3 cup","item":"all-purpose flour"},{"qty":"2 lb","item":"chicken thighs"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 (14.5 oz) can","item":"diced tomatoes"},{"qty":"2 cups","item":"chicken broth"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"1/4 tsp","item":"cayenne pepper"},{"qty":"3 cups","item":"cooked rice"}],"steps":["Cook the oil and flour over medium heat, stirring constantly, into a medium-brown roux, about 15 minutes.","Add the onion, bell pepper, and celery and cook until softened, then stir in the garlic.","Add the tomatoes, broth, Cajun seasoning, and cayenne.","Nestle in the chicken thighs, bring to a simmer, then cover and cook 45 minutes until tender.","Let the sauce thicken uncovered for 10 minutes and adjust seasoning.","Serve over rice."],"time":"1 hr 20 min","serves":6},"fam-c-parmesan-risotto-super-good":{"ingredients":[{"qty":"1 1/2 cups","item":"Arborio rice"},{"qty":"5 cups","item":"warm chicken or vegetable broth"},{"qty":"3 tbsp","item":"butter"},{"qty":"1","item":"shallot, minced"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1/2 cup","item":"white wine"},{"qty":"1 cup","item":"grated Parmesan"},{"qty":"to taste","item":"salt and pepper"},{"qty":"2 tbsp","item":"chopped parsley"}],"steps":["Melt 2 tbsp butter in a wide pan and saute the shallot and garlic until soft.","Add the rice and toast for 1 to 2 minutes until the edges turn translucent.","Pour in the wine and stir until absorbed.","Add the warm broth one ladleful at a time, stirring constantly and letting each addition absorb before the next, about 20 minutes.","Off the heat, stir in the remaining butter and the Parmesan until creamy.","Season to taste, garnish with parsley, and serve."],"time":"35 min","serves":4},"fam-c-chocolate-chess-pie-ii":{"ingredients":[{"qty":"1","item":"9-inch unbaked pie crust"},{"qty":"1/2 cup","item":"unsalted butter, melted"},{"qty":"1 1/2 cups","item":"granulated sugar"},{"qty":"3 tbsp","item":"unsweetened cocoa powder"},{"qty":"2 tbsp","item":"cornmeal"},{"qty":"1/4 tsp","item":"salt"},{"qty":"2","item":"large eggs"},{"qty":"1/2 cup","item":"evaporated milk"},{"qty":"1 tsp","item":"vanilla extract"}],"steps":["Preheat oven to 350F and place the pie crust in a 9-inch pie pan.","In a bowl, whisk together sugar, cocoa powder, cornmeal and salt.","Whisk in the melted butter, eggs, evaporated milk and vanilla until smooth.","Pour the filling into the crust and bake 45 to 55 minutes until the center is just set with a slight jiggle.","Cool completely on a rack before slicing; serve at room temperature or chilled."],"time":"1 hr","serves":8},"fam-c-strawberry-cream-cheese-cobbler":{"ingredients":[{"qty":"4 cups","item":"fresh strawberries, halved"},{"qty":"1 1/4 cups","item":"granulated sugar, divided"},{"qty":"1/2 cup","item":"unsalted butter"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"2 tsp","item":"baking powder"},{"qty":"1/4 tsp","item":"salt"},{"qty":"1 cup","item":"whole milk"},{"qty":"6 oz","item":"cream cheese, cubed"},{"qty":"1 tsp","item":"vanilla extract"}],"steps":["Preheat oven to 350F. Place butter in a 9x13-inch baking dish and melt it in the oven.","Toss strawberries with 1/2 cup sugar and let sit while you make the batter.","Whisk flour, remaining 3/4 cup sugar, baking powder, salt, milk and vanilla into a smooth batter.","Pour the batter over the melted butter without stirring, then spoon the strawberries and their juices evenly on top.","Dot the surface with cubes of cream cheese.","Bake 45 to 55 minutes until golden and bubbling. Cool slightly and serve warm."],"time":"1 hr 10 min","serves":8},"fam-c-the-best-moules-marinieres-sailor-style":{"ingredients":[{"qty":"4 lbs","item":"fresh mussels, scrubbed and debearded"},{"qty":"3 tbsp","item":"unsalted butter"},{"qty":"2","item":"shallots, finely chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 1/2 cups","item":"dry white wine"},{"qty":"2","item":"bay leaves"},{"qty":"1/2 cup","item":"fresh parsley, chopped"},{"qty":"1/4 tsp","item":"freshly ground black pepper"},{"qty":"1","item":"crusty baguette, for serving"}],"steps":["Discard any mussels that are open and do not close when tapped.","Melt butter in a large pot over medium heat and soften the shallots and garlic for 2 to 3 minutes.","Pour in the white wine, add bay leaves and pepper, and bring to a brisk simmer.","Add the mussels, cover, and steam 4 to 6 minutes, shaking the pot occasionally, until the shells open.","Discard any mussels that stayed shut, stir in the parsley, and serve in bowls with the broth and baguette."],"time":"25 min","serves":4},"fam-c-chicken-parmesan":{"ingredients":[{"qty":"4","item":"boneless skinless chicken breasts"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"2","item":"large eggs, beaten"},{"qty":"1 1/2 cups","item":"Italian breadcrumbs"},{"qty":"1/2 cup","item":"grated Parmesan cheese"},{"qty":"2 cups","item":"marinara sauce"},{"qty":"1 1/2 cups","item":"shredded mozzarella"},{"qty":"1/2 cup","item":"olive oil, for frying"},{"qty":"1/4 tsp","item":"salt and pepper"}],"steps":["Pound chicken to even thickness and season with salt and pepper.","Dredge each breast in flour, dip in beaten egg, then coat in breadcrumbs mixed with half the Parmesan.","Fry in olive oil over medium-high heat 3 to 4 minutes per side until golden, then transfer to a baking dish.","Preheat oven to 425F. Spoon marinara over each cutlet and top with mozzarella and remaining Parmesan.","Bake 15 to 20 minutes until the cheese is melted and bubbling and chicken is cooked through.","Rest a few minutes and serve over pasta or with crusty bread."],"time":"45 min","serves":4},"fam-c-oh-so-good-chicken":{"ingredients":[{"qty":"6","item":"bone-in chicken thighs"},{"qty":"1/4 cup","item":"olive oil"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"2 tbsp","item":"honey"},{"qty":"2 tbsp","item":"soy sauce"},{"qty":"1 tbsp","item":"Dijon mustard"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"1/2 tsp","item":"salt and pepper"}],"steps":["Whisk olive oil, garlic, honey, soy sauce, mustard, paprika, thyme, salt and pepper into a marinade.","Coat the chicken thighs and marinate at least 30 minutes.","Preheat oven to 400F and arrange chicken skin-side up in a baking dish.","Roast 35 to 40 minutes, basting once, until the skin is golden and juices run clear.","Rest 5 minutes and spoon pan juices over before serving."],"time":"50 min","serves":4},"fam-c-fideo-with-potatoes-and-ground-beef":{"ingredients":[{"qty":"1 lb","item":"ground beef"},{"qty":"8 oz","item":"fideo (thin noodles)"},{"qty":"2","item":"russet potatoes, diced"},{"qty":"2 tbsp","item":"vegetable oil"},{"qty":"1","item":"onion, chopped"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 can (8 oz)","item":"tomato sauce"},{"qty":"2 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"chili powder"},{"qty":"3 cups","item":"beef broth"},{"qty":"1/2 tsp","item":"salt and pepper"}],"steps":["Heat oil in a large skillet and toast the fideo until golden brown, then remove and set aside.","Brown the ground beef with onion and garlic, draining excess fat.","Add diced potatoes, cumin and chili powder and cook a few minutes.","Stir in tomato sauce, broth and the toasted fideo, scraping up any browned bits.","Cover and simmer 15 to 20 minutes until the noodles and potatoes are tender and most liquid is absorbed.","Season with salt and pepper and serve hot."],"time":"40 min","serves":4},"fam-c-creole-shrimp-mac-and-cheese":{"ingredients":[{"qty":"1 lb","item":"elbow macaroni"},{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"2 tbsp","item":"Creole seasoning, divided"},{"qty":"4 tbsp","item":"butter"},{"qty":"1/4 cup","item":"all-purpose flour"},{"qty":"3 cups","item":"whole milk"},{"qty":"2 cups","item":"shredded sharp cheddar"},{"qty":"1 cup","item":"shredded Monterey Jack"},{"qty":"1","item":"small bell pepper, diced"},{"qty":"2","item":"green onions, sliced"}],"steps":["Cook macaroni to al dente, drain and set aside.","Season shrimp with 1 tablespoon Creole seasoning and saute in 1 tablespoon butter until pink; remove.","Melt remaining butter, soften the bell pepper, then whisk in flour to make a roux.","Gradually whisk in milk and cook until thickened, then stir in cheeses and remaining Creole seasoning until smooth.","Fold in the macaroni and shrimp and transfer to a baking dish.","Bake at 375F for 20 minutes until bubbly, then top with green onions and serve."],"time":"50 min","serves":6},"fam-c-cajun-shrimp-stew":{"ingredients":[{"qty":"2 lbs","item":"shrimp, peeled and deveined"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2","item":"celery stalks, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"4 cups","item":"seafood or chicken stock"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"3","item":"green onions, sliced"},{"qty":"3 cups","item":"cooked white rice, for serving"}],"steps":["Make a dark roux by cooking the oil and flour over medium heat, stirring constantly, until peanut-butter brown, about 15 minutes.","Add onion, bell pepper, celery and garlic and cook until softened.","Slowly whisk in the stock and Cajun seasoning, then simmer 20 minutes until thickened.","Add the shrimp and cook 5 to 7 minutes until pink and just cooked through.","Stir in green onions, adjust seasoning, and serve over rice."],"time":"55 min","serves":6},"fam-c-shrimp-tacos":{"ingredients":[{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1 tbsp","item":"chili powder"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1/2 tsp","item":"garlic powder"},{"qty":"8","item":"small corn or flour tortillas"},{"qty":"2 cups","item":"shredded cabbage"},{"qty":"1","item":"avocado, sliced"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"1","item":"lime, cut into wedges"},{"qty":"1/4 cup","item":"fresh cilantro, chopped"}],"steps":["Toss shrimp with olive oil, chili powder, cumin and garlic powder.","Sear shrimp in a hot skillet 2 minutes per side until pink and opaque.","Warm the tortillas in a dry pan or over a flame.","Stir a squeeze of lime into the sour cream for a quick crema.","Fill tortillas with cabbage, shrimp, avocado and crema, then top with cilantro and serve with lime wedges."],"time":"25 min","serves":4},"fam-c-greek-salad-dressing":{"ingredients":[{"qty":"1/2 cup","item":"extra-virgin olive oil"},{"qty":"3 tbsp","item":"red wine vinegar"},{"qty":"1","item":"lemon, juiced"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1 tsp","item":"Dijon mustard"},{"qty":"1/2 tsp","item":"salt"},{"qty":"1/4 tsp","item":"black pepper"}],"steps":["Combine olive oil, red wine vinegar and lemon juice in a jar.","Add the garlic, oregano, mustard, salt and pepper.","Seal and shake vigorously until emulsified.","Let sit 10 minutes for the flavors to meld, then shake again before dressing your salad."],"time":"10 min","serves":6},"fam-c-hot-fudge-brownie-bread":{"ingredients":[{"qty":"1 cup","item":"all-purpose flour"},{"qty":"3/4 cup","item":"granulated sugar"},{"qty":"1/2 cup","item":"unsweetened cocoa powder"},{"qty":"1 tsp","item":"baking powder"},{"qty":"1/4 tsp","item":"salt"},{"qty":"1/2 cup","item":"unsalted butter, melted"},{"qty":"2","item":"large eggs"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1/2 cup","item":"chocolate chips"},{"qty":"1/2 cup","item":"hot fudge sauce"}],"steps":["Preheat oven to 350F and grease a 9x5-inch loaf pan.","Whisk together flour, sugar, cocoa, baking powder and salt.","Stir in the melted butter, eggs and vanilla until just combined, then fold in the chocolate chips.","Spread half the batter in the pan, swirl in the hot fudge, then top with remaining batter.","Bake 40 to 45 minutes until a toothpick comes out with moist crumbs.","Cool 15 minutes before slicing."],"time":"1 hr","serves":8},"fam-c-a-beignet-recipe-absolutely-anyone-can-m":{"ingredients":[{"qty":"1 1/2 tsp","item":"active dry yeast"},{"qty":"1/2 cup","item":"warm water"},{"qty":"1/2 cup","item":"evaporated milk"},{"qty":"1/4 cup","item":"granulated sugar"},{"qty":"1","item":"large egg"},{"qty":"3 1/2 cups","item":"all-purpose flour"},{"qty":"2 tbsp","item":"butter, softened"},{"qty":"1/2 tsp","item":"salt"},{"qty":"4 cups","item":"vegetable oil, for frying"},{"qty":"1 cup","item":"powdered sugar, for dusting"}],"steps":["Dissolve the yeast in warm water and let it foam for 5 minutes.","Stir in evaporated milk, sugar, egg, butter and salt, then mix in the flour to form a soft dough.","Cover and refrigerate at least 1 hour (or overnight) until chilled and risen.","Roll the dough 1/4 inch thick and cut into 2-inch squares.","Heat oil to 360F and fry the beignets in batches, turning, until puffed and golden, about 2 to 3 minutes.","Drain briefly and dust generously with powdered sugar while warm."],"time":"1 hr 30 min","serves":6},"fam-c-enjoy-have-a-nice-meal-homemade-kentucky":{"ingredients":[{"qty":"4 cups","item":"fresh blackberries"},{"qty":"1 1/2 cups","item":"granulated sugar, divided"},{"qty":"1/2 cup","item":"unsalted butter"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"2 tsp","item":"baking powder"},{"qty":"1/4 tsp","item":"salt"},{"qty":"1 cup","item":"whole milk"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1/2 tsp","item":"ground cinnamon"}],"steps":["Preheat oven to 350F and melt the butter in a 9x13-inch baking dish in the oven.","Toss blackberries with 1/2 cup of the sugar and set aside.","Whisk flour, remaining 1 cup sugar, baking powder, salt, cinnamon, milk and vanilla into a smooth batter.","Pour the batter over the melted butter without stirring, then spoon the blackberries evenly on top.","Bake 45 to 55 minutes until golden and bubbling around the edges.","Cool slightly and serve warm, ideally with vanilla ice cream."],"time":"1 hr 5 min","serves":8},"fam-c-slow-cooker-southwest-cheesy-chicken-and":{"ingredients":[{"qty":"1 1/2 lbs","item":"boneless skinless chicken breasts"},{"qty":"1 cup","item":"long-grain white rice"},{"qty":"1 can (15 oz)","item":"black beans, drained"},{"qty":"1 can (15 oz)","item":"corn, drained"},{"qty":"1 can (10 oz)","item":"diced tomatoes with green chilies"},{"qty":"2 cups","item":"chicken broth"},{"qty":"1 packet","item":"taco seasoning"},{"qty":"2 cups","item":"shredded cheddar cheese"},{"qty":"2","item":"green onions, sliced"}],"steps":["Place chicken in the slow cooker and add rice, black beans, corn, tomatoes, broth and taco seasoning.","Cover and cook on low 4 to 5 hours until the chicken and rice are tender.","Remove the chicken, shred it, and stir it back into the pot.","Sprinkle the cheese over the top, cover, and cook 10 minutes until melted.","Top with green onions and serve."],"time":"5 hr","serves":6},"fam-c-tuscan-tortellini-recipe-easy-skillet-pr":{"ingredients":[{"qty":"20 oz","item":"refrigerated cheese tortellini"},{"qty":"1 lb","item":"Italian sausage, casings removed"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"sun-dried tomatoes, chopped"},{"qty":"1 1/2 cups","item":"heavy cream"},{"qty":"1 cup","item":"chicken broth"},{"qty":"3 cups","item":"fresh spinach"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"1/2 tsp","item":"Italian seasoning"}],"steps":["Brown the sausage in a large skillet, breaking it up, until cooked through.","Add garlic and sun-dried tomatoes and cook 1 minute until fragrant.","Pour in the cream and broth, stir in Italian seasoning, and bring to a gentle simmer.","Add the tortellini and simmer 5 to 7 minutes until tender.","Stir in the spinach and Parmesan until the spinach wilts and the sauce thickens, then serve."],"time":"30 min","serves":4},"fam-c-garlic-knot-pizza-bake":{"ingredients":[{"qty":"1 lb","item":"refrigerated pizza dough"},{"qty":"4 tbsp","item":"butter, melted"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1/2 cup","item":"grated Parmesan, divided"},{"qty":"1 1/2 cups","item":"shredded mozzarella"},{"qty":"1 cup","item":"pizza sauce, plus more for dipping"},{"qty":"1 cup","item":"sliced pepperoni"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Preheat oven to 400F and grease a 9x13-inch baking dish.","Cut the pizza dough into 1-inch pieces and toss with the melted butter, garlic, oregano and half the Parmesan.","Scatter the dough pieces in the dish, then dollop the pizza sauce over and around them.","Top with mozzarella, remaining Parmesan and pepperoni.","Bake 25 to 30 minutes until golden and the dough is cooked through.","Sprinkle with parsley and serve with extra warm pizza sauce."],"time":"40 min","serves":6},"fam-c-shrimp-pho":{"ingredients":[{"qty":"8 oz","item":"flat rice noodles"},{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"8 cups","item":"chicken or seafood broth"},{"qty":"1","item":"onion, halved"},{"qty":"3-inch piece","item":"fresh ginger, halved"},{"qty":"3","item":"star anise"},{"qty":"1","item":"cinnamon stick"},{"qty":"2 tbsp","item":"fish sauce"},{"qty":"1 cup","item":"bean sprouts"},{"qty":"1","item":"lime, cut into wedges"},{"qty":"1","item":"handful fresh basil and cilantro"}],"steps":["Char the onion and ginger directly over a flame or under the broiler until fragrant.","Add them to the broth with star anise, cinnamon and fish sauce and simmer 30 minutes, then strain.","Soak the rice noodles in hot water until pliable, then divide among bowls.","Return the broth to a boil and poach the shrimp 2 to 3 minutes until pink.","Ladle the hot broth and shrimp over the noodles and serve with bean sprouts, herbs and lime."],"time":"50 min","serves":4},"fam-c-camellias-famous-new-orleans-style-red-b":{"ingredients":[{"qty":"1 lb","item":"dried red kidney beans, soaked overnight"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"1","item":"ham hock"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2","item":"celery stalks, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"2","item":"bay leaves"},{"qty":"1 tsp","item":"Cajun seasoning"},{"qty":"8 cups","item":"water"},{"qty":"4 cups","item":"cooked white rice, for serving"}],"steps":["Drain the soaked beans. Brown the andouille in a large pot, then remove.","Soften the onion, bell pepper, celery and garlic in the drippings.","Add the beans, ham hock, bay leaves, Cajun seasoning, sausage and water.","Bring to a boil, then simmer covered 2 to 2 1/2 hours until the beans are creamy, stirring occasionally.","Mash some beans against the pot to thicken, discard the bay leaves and ham hock bone, and season to taste.","Serve over white rice."],"time":"3 hr","serves":6},"fam-c-blueberry-gin-daisy":{"ingredients":[{"qty":"2 oz","item":"gin"},{"qty":"3/4 oz","item":"fresh lemon juice"},{"qty":"1/2 oz","item":"simple syrup"},{"qty":"1/4 cup","item":"fresh blueberries"},{"qty":"1/2 oz","item":"triple sec"},{"qty":"1","item":"splash club soda"},{"qty":"1 cup","item":"ice"},{"qty":"1","item":"lemon twist, for garnish"}],"steps":["Muddle the blueberries with simple syrup in a shaker.","Add the gin, lemon juice, triple sec and ice.","Shake well until chilled.","Strain into an ice-filled glass and top with a splash of club soda.","Garnish with a lemon twist and a few blueberries."],"time":"5 min","serves":1},"fam-c-chicken-sauce-piquante-by-emeril-lagasse":{"ingredients":[{"qty":"3 lbs","item":"chicken pieces"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2","item":"celery stalks, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 can (28 oz)","item":"crushed tomatoes"},{"qty":"2 cups","item":"chicken stock"},{"qty":"1 tbsp","item":"Cajun seasoning"},{"qty":"3","item":"green onions, sliced"},{"qty":"4 cups","item":"cooked rice, for serving"}],"steps":["Season the chicken with Cajun seasoning and brown in the oil, then set aside.","Whisk the flour into the drippings and cook into a brown roux.","Add onion, bell pepper, celery and garlic and cook until softened.","Stir in the tomatoes and stock, return the chicken, and bring to a simmer.","Cover and simmer 45 minutes to 1 hour until the chicken is tender and the sauce is rich.","Stir in green onions and serve over rice."],"time":"1 hr 30 min","serves":6},"fam-c-easy-gnocchi-with-creamy-herb-sauce":{"ingredients":[{"qty":"1 lb","item":"potato gnocchi"},{"qty":"2 tbsp","item":"butter"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"2 tbsp","item":"fresh parsley, chopped"},{"qty":"1 tbsp","item":"fresh chives, chopped"},{"qty":"1 tsp","item":"fresh thyme leaves"},{"qty":"1/4 tsp","item":"salt and pepper"}],"steps":["Cook the gnocchi in salted boiling water until they float, then drain.","Melt the butter in a skillet and saute the garlic until fragrant.","Pour in the cream and simmer 2 to 3 minutes until slightly thickened.","Stir in the Parmesan and fresh herbs until smooth and season with salt and pepper.","Toss the gnocchi in the sauce to coat and serve immediately."],"time":"20 min","serves":4},"fam-c-tilapia-with-green-beans":{"ingredients":[{"qty":"4","item":"tilapia fillets"},{"qty":"12 oz","item":"fresh green beans, trimmed"},{"qty":"3 tbsp","item":"olive oil, divided"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1","item":"lemon, sliced"},{"qty":"1 tsp","item":"paprika"},{"qty":"1/2 tsp","item":"dried oregano"},{"qty":"1/2 tsp","item":"salt and pepper"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Preheat oven to 400F. Toss green beans with 1 tablespoon olive oil, garlic, salt and pepper on a sheet pan.","Roast the beans 8 minutes to give them a head start.","Pat the tilapia dry, rub with remaining oil, paprika, oregano, salt and pepper.","Nestle the fillets among the beans, top with lemon slices, and roast 12 to 15 minutes until the fish flakes easily.","Sprinkle with parsley and serve."],"time":"30 min","serves":4},"fam-c-crawfish-etouffee---louisianas-best-phot":{"ingredients":[{"qty":"1 lb","item":"crawfish tail meat"},{"qty":"1/2 cup","item":"butter"},{"qty":"1/3 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2","item":"celery stalks, chopped"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"2 cups","item":"seafood stock"},{"qty":"1 tsp","item":"Cajun seasoning"},{"qty":"3","item":"green onions, sliced"},{"qty":"4 cups","item":"cooked white rice, for serving"}],"steps":["Melt the butter and whisk in the flour, cooking into a blond roux.","Add onion, bell pepper, celery and garlic and cook until softened.","Gradually whisk in the seafood stock and Cajun seasoning and simmer 15 minutes until thickened.","Stir in the crawfish tails and cook gently 8 to 10 minutes.","Add green onions, adjust seasoning, and serve over rice."],"time":"45 min","serves":4},"fam-c-chocolate-fondue-2":{"ingredients":[{"qty":"8 oz","item":"semisweet chocolate, chopped"},{"qty":"1/2 cup","item":"heavy cream"},{"qty":"2 tbsp","item":"butter"},{"qty":"1 tbsp","item":"liqueur or vanilla extract"},{"qty":"1","item":"pinch of salt"},{"qty":"2 cups","item":"strawberries, for dipping"},{"qty":"2 cups","item":"cubed pound cake, for dipping"},{"qty":"2","item":"bananas, sliced, for dipping"}],"steps":["Heat the cream and butter in a saucepan until steaming but not boiling.","Remove from heat and add the chopped chocolate, letting it sit 1 minute.","Whisk until smooth, then stir in the liqueur or vanilla and a pinch of salt.","Transfer to a fondue pot or warm bowl to keep it fluid.","Serve with strawberries, pound cake and banana for dipping."],"time":"15 min","serves":6},"fam-c-chocolate-chip-cookie-dough-cheesecake":{"ingredients":[{"qty":"2 cups","item":"chocolate sandwich cookie crumbs"},{"qty":"5 tbsp","item":"butter, melted"},{"qty":"24 oz","item":"cream cheese, softened"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"3","item":"large eggs"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"1 cup","item":"edible cookie dough bites (heat-treated flour, no eggs)"},{"qty":"1/2 cup","item":"mini chocolate chips"}],"steps":["Preheat oven to 325F. Mix the cookie crumbs with melted butter and press into the bottom of a 9-inch springform pan.","Beat the cream cheese and sugar until smooth, then add the eggs one at a time.","Mix in the vanilla and sour cream until just combined.","Pour half the batter over the crust, scatter cookie dough bites, then add remaining batter and top with mini chips.","Bake 55 to 65 minutes until the edges are set and the center barely jiggles.","Cool, then refrigerate at least 4 hours before slicing."],"time":"5 hr","serves":12},"fam-c-grilled-pesto-chicken-kabobs":{"ingredients":[{"qty":"1 1/2 lbs","item":"boneless chicken breast, cubed"},{"qty":"1/2 cup","item":"basil pesto"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"1","item":"red bell pepper, cut into chunks"},{"qty":"1","item":"zucchini, sliced thick"},{"qty":"1","item":"red onion, cut into chunks"},{"qty":"1/2 tsp","item":"salt and pepper"},{"qty":"8","item":"wooden or metal skewers"}],"steps":["Toss the chicken with pesto, olive oil and lemon juice and marinate at least 30 minutes.","Soak wooden skewers in water if using.","Thread the chicken, bell pepper, zucchini and onion alternately onto the skewers and season with salt and pepper.","Grill over medium-high heat 10 to 12 minutes, turning, until the chicken is cooked through and lightly charred.","Rest a couple of minutes and serve."],"time":"45 min","serves":4},"fam-c-chicken-scarpariello":{"ingredients":[{"qty":"3 lbs","item":"bone-in chicken thighs and drumsticks"},{"qty":"1 lb","item":"Italian sausage links, cut into chunks"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1","item":"onion, sliced"},{"qty":"1","item":"red bell pepper, sliced"},{"qty":"5 cloves","item":"garlic, sliced"},{"qty":"1/2 cup","item":"pickled cherry peppers, plus 1/4 cup brine"},{"qty":"1 cup","item":"chicken broth"},{"qty":"1/2 cup","item":"white wine"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Season the chicken and brown in olive oil in a large skillet, then set aside.","Brown the sausage chunks in the same pan and set aside with the chicken.","Saute the onion, bell pepper and garlic until softened.","Add the wine, broth, cherry peppers and brine, scraping up the browned bits.","Return the chicken and sausage, cover, and simmer 25 to 30 minutes until cooked through.","Sprinkle with parsley and serve."],"time":"55 min","serves":6},"fam-c-spicy-indian-curry-recipe-with-chicken":{"ingredients":[{"qty":"2 lbs","item":"boneless chicken thighs, cubed"},{"qty":"3 tbsp","item":"vegetable oil"},{"qty":"2","item":"onions, finely chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"2 tbsp","item":"curry powder"},{"qty":"1 tsp","item":"ground turmeric"},{"qty":"1 tsp","item":"cayenne pepper"},{"qty":"1 can (14 oz)","item":"crushed tomatoes"},{"qty":"1 cup","item":"coconut milk"},{"qty":"1/2 tsp","item":"salt"},{"qty":"2 tbsp","item":"fresh cilantro, chopped"}],"steps":["Heat the oil and saute the onions until deep golden, about 8 minutes.","Add garlic and ginger and cook 1 minute, then stir in curry powder, turmeric and cayenne.","Add the chicken and brown on all sides.","Stir in the crushed tomatoes and simmer 10 minutes.","Add the coconut milk and salt and simmer 15 to 20 minutes until the chicken is tender and the sauce thickens.","Garnish with cilantro and serve with rice or naan."],"time":"50 min","serves":6},"fam-c-french-75":{"ingredients":[{"qty":"1 oz","item":"gin"},{"qty":"1/2 oz","item":"fresh lemon juice"},{"qty":"1/2 oz","item":"simple syrup"},{"qty":"3 oz","item":"Champagne, chilled"},{"qty":"1 cup","item":"ice"},{"qty":"1","item":"lemon twist, for garnish"}],"steps":["Add the gin, lemon juice and simple syrup to a shaker with ice.","Shake until well chilled.","Strain into a Champagne flute.","Top with chilled Champagne and garnish with a lemon twist."],"time":"5 min","serves":1},"fam-c-halloween-oreo-brownie-pizza":{"ingredients":[{"qty":"1 box","item":"brownie mix (plus called-for eggs and oil)"},{"qty":"8 oz","item":"cream cheese, softened"},{"qty":"1/2 cup","item":"powdered sugar"},{"qty":"1 tsp","item":"vanilla extract"},{"qty":"12","item":"Halloween Oreos, roughly chopped"},{"qty":"1/2 cup","item":"candy corn"},{"qty":"1/2 cup","item":"orange and black sprinkles"},{"qty":"1/4 cup","item":"melted chocolate, for drizzling"}],"steps":["Prepare the brownie batter and spread it onto a greased 12-inch round pizza pan.","Bake at 350F for 18 to 22 minutes until set, then cool completely.","Beat the cream cheese, powdered sugar and vanilla until smooth and spread over the brownie base.","Top with chopped Oreos, candy corn and sprinkles.","Drizzle with melted chocolate, chill 15 minutes, then slice into wedges."],"time":"50 min","serves":12},"fam-c-easy-chorizo-chicken-and-shellfish-paell":{"ingredients":[{"qty":"2 tbsp","item":"olive oil"},{"qty":"6 oz","item":"Spanish chorizo, sliced"},{"qty":"1 lb","item":"boneless chicken thighs, cut into chunks"},{"qty":"1","item":"onion, finely chopped"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1","item":"red bell pepper, sliced"},{"qty":"2 cups","item":"Bomba or short-grain rice"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1 pinch","item":"saffron threads"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"4 cups","item":"chicken stock, warm"},{"qty":"1/2 lb","item":"shrimp, peeled"},{"qty":"1/2 lb","item":"mussels, scrubbed"},{"qty":"1 cup","item":"frozen peas"},{"qty":"1","item":"lemon, cut into wedges"}],"steps":["Heat olive oil in a wide paella pan over medium-high heat and brown the chorizo and chicken until golden; remove and set aside.","Add onion, garlic, and bell pepper to the pan and cook until softened, about 5 minutes.","Stir in the rice, smoked paprika, and saffron, toasting for 1 minute.","Add the tomatoes and warm stock, return the chorizo and chicken, and simmer gently without stirring for 15 minutes.","Nestle the shrimp and mussels into the rice, scatter the peas over top, and cook until shrimp are pink and mussels open, about 8 minutes.","Rest off the heat for 5 minutes, then serve with lemon wedges."],"time":"1 hr","serves":6},"fam-c-pan-seared-chicken-breasts-with-creamy-m":{"ingredients":[{"qty":"4","item":"boneless skinless chicken breasts"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"3 tbsp","item":"butter"},{"qty":"8 oz","item":"cremini mushrooms, sliced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"chicken broth"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"1 tsp","item":"fresh thyme leaves"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Season the chicken with salt and pepper.","Heat olive oil in a skillet over medium-high heat and sear the chicken 5-6 minutes per side until golden and cooked through; remove and keep warm.","Melt the butter in the same pan and saute the mushrooms until browned, about 5 minutes.","Add the garlic and cook 30 seconds, then pour in the broth and scrape up the browned bits.","Stir in the cream, Parmesan, and thyme and simmer until thickened, about 4 minutes.","Return the chicken to the sauce, spoon over to coat, and garnish with parsley."],"time":"35 min","serves":4},"fam-c-file-gumbo-with-rabbit-andouille-sausage":{"ingredients":[{"qty":"1","item":"rabbit, cut into pieces"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"3/4 cup","item":"vegetable oil"},{"qty":"3/4 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2 stalks","item":"celery, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"8 cups","item":"chicken stock"},{"qty":"2","item":"bay leaves"},{"qty":"1 tsp","item":"cayenne pepper"},{"qty":"1 tbsp","item":"filé powder"},{"qty":"4","item":"green onions, sliced"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"cooked white rice"}],"steps":["Brown the rabbit pieces and andouille in a heavy pot, then remove and set aside.","Make a dark roux by whisking the oil and flour over medium heat until chocolate-colored, about 20 minutes.","Add the onion, bell pepper, celery, and garlic to the roux and cook until softened.","Slowly whisk in the stock, then return the rabbit and sausage with the bay leaves and cayenne.","Simmer uncovered for about 1.5 hours until the rabbit is tender, then remove the meat, shred, and return it to the pot.","Turn off the heat, stir in the filé powder and green onions, season, and serve over rice."],"time":"2 hr 30 min","serves":8},"fam-c-searedscallops-cajun-cream-sauce":{"ingredients":[{"qty":"1 lb","item":"large sea scallops, patted dry"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"3 tbsp","item":"butter"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"heavy cream"},{"qty":"1/4 cup","item":"chicken broth"},{"qty":"1/4 cup","item":"grated Parmesan"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Season the scallops on both sides with Cajun seasoning.","Heat olive oil in a skillet over high heat and sear the scallops 2 minutes per side until a golden crust forms; remove.","Lower the heat, melt the butter, and saute the garlic for 30 seconds.","Pour in the cream and broth, simmer 3 minutes, then stir in the Parmesan and lemon juice.","Return the scallops to warm through, garnish with parsley, and serve."],"time":"25 min","serves":4},"fam-c-horseradish-cheddar-chicken-salad":{"ingredients":[{"qty":"3 cups","item":"cooked chicken, diced"},{"qty":"1 cup","item":"sharp cheddar, cubed"},{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"2 tbsp","item":"prepared horseradish"},{"qty":"1 tbsp","item":"Dijon mustard"},{"qty":"2 stalks","item":"celery, finely diced"},{"qty":"2","item":"green onions, sliced"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Whisk together the mayonnaise, horseradish, Dijon, and lemon juice in a large bowl.","Add the chicken, cheddar, celery, and green onions.","Fold everything together until evenly coated.","Season with salt and pepper, then chill at least 30 minutes before serving."],"time":"15 min","serves":4},"fam-c-the-glow-up-smoothie-recipe-for-firmer-s":{"ingredients":[{"qty":"1 cup","item":"frozen mixed berries"},{"qty":"1/2","item":"frozen banana"},{"qty":"1/2","item":"avocado"},{"qty":"1 cup","item":"spinach"},{"qty":"1 cup","item":"almond milk"},{"qty":"1 tbsp","item":"collagen powder"},{"qty":"1 tbsp","item":"chia seeds"},{"qty":"1 tsp","item":"honey"}],"steps":["Add the almond milk, spinach, and avocado to a blender and blend until smooth.","Add the berries, banana, collagen powder, chia seeds, and honey.","Blend on high until creamy, adding more almond milk if needed.","Pour into a glass and serve immediately."],"time":"5 min","serves":1},"fam-c-horsey-eggs":{"ingredients":[{"qty":"6","item":"hard-boiled eggs, peeled and halved"},{"qty":"3 tbsp","item":"mayonnaise"},{"qty":"2 tsp","item":"prepared horseradish"},{"qty":"1 tsp","item":"Dijon mustard"},{"qty":"1 pinch","item":"paprika"},{"qty":"1 tbsp","item":"chives, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Scoop the yolks from the halved eggs into a bowl.","Mash the yolks with the mayonnaise, horseradish, and Dijon until smooth.","Season with salt and pepper, then spoon or pipe the filling back into the egg whites.","Sprinkle with paprika and chives and serve chilled."],"time":"20 min","serves":4},"fam-c-spanish-chicken-and-potato-roast":{"ingredients":[{"qty":"8","item":"bone-in chicken thighs"},{"qty":"1.5 lb","item":"baby potatoes, halved"},{"qty":"1","item":"red onion, cut into wedges"},{"qty":"4 oz","item":"Spanish chorizo, sliced"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"2 tsp","item":"smoked paprika"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1","item":"lemon, juiced"},{"qty":"to taste","item":"salt and pepper"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Preheat oven to 425F.","Toss the potatoes, onion, and chorizo with 2 tbsp olive oil, half the paprika, and salt in a large roasting pan.","Rub the chicken with the remaining oil, paprika, garlic, oregano, lemon juice, salt, and pepper.","Nestle the chicken among the potatoes, skin side up.","Roast for 40-45 minutes until the chicken is golden and the potatoes are tender.","Garnish with parsley and serve."],"time":"55 min","serves":4},"fam-c-best-buttermilk-blue-cheese-dressing":{"ingredients":[{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"1/2 cup","item":"buttermilk"},{"qty":"4 oz","item":"blue cheese, crumbled"},{"qty":"1 tbsp","item":"white wine vinegar"},{"qty":"1 clove","item":"garlic, grated"},{"qty":"1 tbsp","item":"fresh chives, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Whisk together the mayonnaise, sour cream, and buttermilk until smooth.","Stir in the vinegar, garlic, and chives.","Fold in the blue cheese, leaving some larger crumbles for texture.","Season with salt and pepper and chill at least 1 hour before serving."],"time":"10 min","serves":8},"fam-c-gnocchi-i":{"ingredients":[{"qty":"2 lb","item":"russet potatoes"},{"qty":"1.5 cups","item":"all-purpose flour"},{"qty":"1","item":"egg, beaten"},{"qty":"1 tsp","item":"salt"},{"qty":"1 pinch","item":"nutmeg"}],"steps":["Boil the potatoes whole in their skins until fork-tender, about 40 minutes, then drain and peel.","Rice or mash the warm potatoes and spread on a work surface to cool slightly.","Sprinkle with flour, salt, and nutmeg, add the egg, and gently knead into a soft dough.","Roll pieces into ropes, cut into 1-inch pillows, and press with a fork to ridge.","Boil in salted water until they float, about 2-3 minutes, then drain and toss with your favorite sauce."],"time":"1 hr 15 min","serves":4},"fam-c-sweet-little-bluebird-white-cheese-chick":{"ingredients":[{"qty":"9","item":"lasagna noodles"},{"qty":"1/2 cup","item":"butter"},{"qty":"1","item":"onion, chopped"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"2 cups","item":"chicken broth"},{"qty":"1.5 cups","item":"milk"},{"qty":"4 cups","item":"shredded mozzarella"},{"qty":"1 cup","item":"grated Parmesan"},{"qty":"1 tsp","item":"dried basil"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"2 cups","item":"cooked chicken, shredded"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 350F and cook the lasagna noodles until al dente.","Melt the butter and saute the onion and garlic, then whisk in the flour and cook 1 minute.","Gradually add the broth and milk, stirring until thickened, then stir in half the mozzarella, the Parmesan, basil, and oregano.","Spread a layer of sauce in a baking dish, then layer noodles, chicken, and sauce, repeating to fill the dish.","Top with the remaining mozzarella and bake 35-40 minutes until bubbly and golden.","Rest 10 minutes before slicing."],"time":"1 hr 15 min","serves":8},"fam-c-gang-gai-khao-mun-thai-chicken-curry":{"ingredients":[{"qty":"1.5 lb","item":"boneless chicken thighs, cubed"},{"qty":"3 tbsp","item":"red or yellow Thai curry paste"},{"qty":"2 cans (14 oz each)","item":"coconut milk"},{"qty":"2 tbsp","item":"fish sauce"},{"qty":"1 tbsp","item":"palm or brown sugar"},{"qty":"1","item":"onion, sliced"},{"qty":"2","item":"potatoes, cubed"},{"qty":"3","item":"kaffir lime leaves"},{"qty":"1 cup","item":"jasmine rice"},{"qty":"2 tbsp","item":"vegetable oil"},{"qty":"for garnish","item":"Thai basil"}],"steps":["Cook the jasmine rice according to package directions.","Heat the oil and fry the curry paste with the thick cream from the top of one can of coconut milk until fragrant.","Add the chicken and brown lightly, then pour in the remaining coconut milk.","Add the onion, potatoes, lime leaves, fish sauce, and sugar.","Simmer gently 25-30 minutes until the chicken and potatoes are tender.","Garnish with Thai basil and serve over jasmine rice."],"time":"50 min","serves":4},"fam-c-chicken-penne-pasta-bake":{"ingredients":[{"qty":"1 lb","item":"penne pasta"},{"qty":"2 cups","item":"cooked chicken, diced"},{"qty":"3 cups","item":"marinara sauce"},{"qty":"1 cup","item":"ricotta cheese"},{"qty":"2 cups","item":"shredded mozzarella"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"to taste","item":"salt and pepper"},{"qty":"2 tbsp","item":"fresh basil, chopped"}],"steps":["Preheat oven to 375F and cook the penne until just al dente.","Toss the pasta with the chicken, marinara, garlic, Italian seasoning, and ricotta.","Spread into a greased baking dish and top with mozzarella and Parmesan.","Bake 25-30 minutes until bubbly and golden.","Garnish with fresh basil and serve."],"time":"45 min","serves":6},"fam-c-pumpkin-roll":{"ingredients":[{"qty":"3","item":"eggs"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"2/3 cup","item":"pumpkin puree"},{"qty":"3/4 cup","item":"all-purpose flour"},{"qty":"1 tsp","item":"baking soda"},{"qty":"2 tsp","item":"pumpkin pie spice"},{"qty":"8 oz","item":"cream cheese, softened"},{"qty":"1 cup","item":"powdered sugar"},{"qty":"6 tbsp","item":"butter, softened"},{"qty":"1 tsp","item":"vanilla extract"}],"steps":["Preheat oven to 375F and line a jelly-roll pan with parchment.","Beat the eggs and granulated sugar until thick, then mix in the pumpkin.","Fold in the flour, baking soda, and pumpkin pie spice, then spread evenly in the pan.","Bake 13-15 minutes, then immediately turn out onto a powdered-sugar-dusted towel and roll up tightly; cool completely.","Beat the cream cheese, powdered sugar, butter, and vanilla until smooth.","Unroll the cake, spread with filling, re-roll, and chill before slicing."],"time":"1 hr","serves":8},"fam-c-cranberry-sauce":{"ingredients":[{"qty":"12 oz","item":"fresh or frozen cranberries"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1 cup","item":"water"},{"qty":"1","item":"orange, zested and juiced"},{"qty":"1","item":"cinnamon stick"}],"steps":["Combine the water, sugar, orange juice, and zest in a saucepan and bring to a boil.","Add the cranberries and cinnamon stick and return to a simmer.","Cook 10-12 minutes until the cranberries burst and the sauce thickens.","Remove the cinnamon stick, cool, and chill before serving."],"time":"20 min","serves":8},"fam-c-copycat-costcoTM-almond-poppy-muffins":{"ingredients":[{"qty":"2.5 cups","item":"all-purpose flour"},{"qty":"1.5 cups","item":"granulated sugar"},{"qty":"1 tbsp","item":"poppy seeds"},{"qty":"1 tsp","item":"baking powder"},{"qty":"1/2 tsp","item":"baking soda"},{"qty":"1/2 tsp","item":"salt"},{"qty":"2","item":"eggs"},{"qty":"1 cup","item":"milk"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1.5 tsp","item":"almond extract"},{"qty":"1/2 cup","item":"sliced almonds"}],"steps":["Preheat oven to 375F and line a muffin tin.","Whisk together the flour, sugar, poppy seeds, baking powder, baking soda, and salt.","In another bowl whisk the eggs, milk, oil, and almond extract.","Combine the wet and dry ingredients just until moistened.","Divide into the muffin cups, top with sliced almonds, and bake 18-22 minutes until golden."],"time":"35 min","serves":12},"fam-c-roasted-asparagus-with-lemon-vinaigrette":{"ingredients":[{"qty":"1.5 lb","item":"asparagus, trimmed"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"lemon, zested and juiced"},{"qty":"1 tbsp","item":"Dijon mustard"},{"qty":"1 clove","item":"garlic, minced"},{"qty":"2 tbsp","item":"extra-virgin olive oil"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 425F.","Toss the asparagus with olive oil, salt, and pepper and spread on a baking sheet.","Roast 12-15 minutes until tender-crisp.","Whisk together the lemon zest, lemon juice, Dijon, garlic, and extra-virgin olive oil.","Drizzle the vinaigrette over the warm asparagus and serve."],"time":"25 min","serves":4},"fam-c-chicken-piccata-pasta-toss":{"ingredients":[{"qty":"12 oz","item":"linguine"},{"qty":"1 lb","item":"chicken breast, thinly sliced"},{"qty":"1/3 cup","item":"all-purpose flour"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"3 tbsp","item":"butter"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"chicken broth"},{"qty":"1/4 cup","item":"lemon juice"},{"qty":"3 tbsp","item":"capers, drained"},{"qty":"1/4 cup","item":"fresh parsley, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the linguine in salted water until al dente, reserving some pasta water.","Dredge the chicken in flour and sear in olive oil until golden and cooked through; remove.","Melt the butter in the pan, saute the garlic, then add the broth, lemon juice, and capers, scraping up the browned bits.","Simmer 3 minutes, then return the chicken and add the drained pasta.","Toss to coat, loosening with pasta water as needed, then finish with parsley, salt, and pepper."],"time":"35 min","serves":4},"fam-c-potato-dinner-rolls":{"ingredients":[{"qty":"1 cup","item":"mashed potatoes, cooled"},{"qty":"1 cup","item":"warm milk"},{"qty":"2 1/4 tsp","item":"active dry yeast"},{"qty":"1/4 cup","item":"sugar"},{"qty":"1/3 cup","item":"butter, melted"},{"qty":"1","item":"egg"},{"qty":"1 tsp","item":"salt"},{"qty":"4 cups","item":"all-purpose flour"}],"steps":["Dissolve the yeast and sugar in the warm milk and let it foam, about 5 minutes.","Stir in the mashed potatoes, melted butter, egg, and salt.","Gradually mix in the flour and knead into a soft, smooth dough.","Cover and let rise until doubled, about 1 hour.","Shape into 15 rolls in a greased pan and let rise 30 minutes more.","Bake at 375F for 18-20 minutes until golden, then brush with butter."],"time":"2 hr 30 min","serves":15},"fam-c-royal-street-red-beans":{"ingredients":[{"qty":"1 lb","item":"dried red kidney beans, soaked overnight"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"1","item":"ham hock"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2 stalks","item":"celery, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"2","item":"bay leaves"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"1/2 tsp","item":"cayenne pepper"},{"qty":"8 cups","item":"water or chicken stock"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"cooked white rice"}],"steps":["Brown the andouille in a heavy pot, then add the onion, bell pepper, celery, and garlic and cook until softened.","Add the drained beans, ham hock, bay leaves, thyme, cayenne, and water.","Bring to a boil, then reduce to a low simmer and cook 2-2.5 hours until the beans are creamy.","Mash some of the beans against the side of the pot to thicken.","Remove the ham hock, shred the meat back in, season, and serve over rice."],"time":"3 hr","serves":6},"fam-c-sheet-pan-harissa-and-orange-chicken-wit":{"ingredients":[{"qty":"8","item":"bone-in chicken thighs"},{"qty":"3 tbsp","item":"harissa paste"},{"qty":"1","item":"orange, zested and juiced"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"2 cans (15 oz each)","item":"chickpeas, drained"},{"qty":"1","item":"red onion, cut into wedges"},{"qty":"1 tsp","item":"honey"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for garnish","item":"fresh cilantro"}],"steps":["Preheat oven to 425F.","Whisk together the harissa, orange zest and juice, olive oil, garlic, cumin, honey, and salt.","Toss the chickpeas and onion with a third of the marinade and spread on a sheet pan.","Coat the chicken in the remaining marinade and arrange skin side up over the chickpeas.","Roast 35-40 minutes until the chicken is browned and cooked through.","Garnish with cilantro and serve."],"time":"50 min","serves":4},"fam-c-chicken-noodle-soup":{"ingredients":[{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"3","item":"carrots, sliced"},{"qty":"3 stalks","item":"celery, sliced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"8 cups","item":"chicken broth"},{"qty":"1 lb","item":"boneless chicken breast"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"2","item":"bay leaves"},{"qty":"8 oz","item":"egg noodles"},{"qty":"2 tbsp","item":"fresh parsley, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Heat the oil and saute the onion, carrots, celery, and garlic until softened, about 6 minutes.","Add the broth, chicken, thyme, and bay leaves and bring to a simmer.","Cook 20 minutes until the chicken is done, then remove, shred, and return it to the pot.","Add the egg noodles and cook until tender, about 8 minutes.","Season with salt and pepper, stir in the parsley, and serve."],"time":"45 min","serves":6},"fam-c-frog-leg-sauce-piquante":{"ingredients":[{"qty":"2 lb","item":"frog legs"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2 stalks","item":"celery, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"2 cups","item":"chicken stock"},{"qty":"1 tsp","item":"cayenne pepper"},{"qty":"2","item":"bay leaves"},{"qty":"3","item":"green onions, sliced"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"cooked white rice"}],"steps":["Season and lightly brown the frog legs in oil, then set aside.","Make a medium-brown roux with the oil and flour, whisking over medium heat.","Add the onion, bell pepper, celery, and garlic and cook until softened.","Stir in the tomatoes, stock, cayenne, and bay leaves and simmer 20 minutes.","Return the frog legs and simmer gently until tender, about 25 minutes.","Stir in the green onions, season, and serve over rice."],"time":"1 hr 15 min","serves":4},"fam-c-best-lentil-soup-recipe-how-to-make-lent":{"ingredients":[{"qty":"3 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"2","item":"carrots, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"tomato paste"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1.5 cups","item":"brown or green lentils, rinsed"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"6 cups","item":"vegetable broth"},{"qty":"2 cups","item":"chopped spinach"},{"qty":"1 tbsp","item":"lemon juice"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Heat the oil and saute the onion, carrots, and celery until softened, about 7 minutes.","Add the garlic, tomato paste, cumin, and paprika and cook 1 minute.","Stir in the lentils, tomatoes, and broth and bring to a boil.","Reduce heat and simmer 30-35 minutes until the lentils are tender.","Stir in the spinach and lemon juice, season, and serve."],"time":"50 min","serves":6},"fam-c-slow-cooker-pinto-beans":{"ingredients":[{"qty":"1 lb","item":"dried pinto beans, rinsed"},{"qty":"1","item":"onion, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1","item":"jalapeno, diced"},{"qty":"1","item":"ham hock or 4 oz bacon"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"chili powder"},{"qty":"2","item":"bay leaves"},{"qty":"6 cups","item":"water or chicken broth"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Add the beans, onion, garlic, jalapeno, ham hock, cumin, chili powder, and bay leaves to the slow cooker.","Pour in the water and stir to combine.","Cover and cook on low for 8 hours or high for 5 hours until the beans are tender.","Remove the ham hock, shred any meat back in, and discard the bay leaves.","Season with salt and pepper and serve."],"time":"8 hr","serves":6},"fam-c-carnival-worthy-angel-wings":{"ingredients":[{"qty":"2 cups","item":"all-purpose flour"},{"qty":"3","item":"egg yolks"},{"qty":"2 tbsp","item":"sugar"},{"qty":"2 tbsp","item":"sour cream"},{"qty":"1 tbsp","item":"rum or vodka"},{"qty":"1 pinch","item":"salt"},{"qty":"for frying","item":"vegetable oil"},{"qty":"for dusting","item":"powdered sugar"}],"steps":["Beat the egg yolks with the sugar, sour cream, rum, and salt.","Mix in the flour and knead into a stiff dough, then rest 20 minutes.","Roll the dough very thin and cut into strips; make a slit in each center and pull one end through to form a bow.","Heat oil to 350F and fry the wings a few at a time until golden, about 1 minute per side.","Drain on paper towels and dust generously with powdered sugar."],"time":"45 min","serves":8},"fam-c-baja-california-style-shrimp-tacos":{"ingredients":[{"qty":"1 lb","item":"shrimp, peeled"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"1 cup","item":"cold beer or soda water"},{"qty":"1 tsp","item":"chili powder"},{"qty":"for frying","item":"vegetable oil"},{"qty":"8","item":"corn tortillas"},{"qty":"2 cups","item":"shredded cabbage"},{"qty":"1/2 cup","item":"mayonnaise"},{"qty":"2 tbsp","item":"lime juice"},{"qty":"1 tsp","item":"hot sauce"},{"qty":"for serving","item":"fresh cilantro and lime wedges"}],"steps":["Whisk the flour, beer, and chili powder into a thin batter.","Heat oil to 375F, dip the shrimp in batter, and fry until golden and crisp, about 2-3 minutes; drain.","Stir together the mayonnaise, lime juice, and hot sauce to make the crema.","Warm the tortillas and top with cabbage, fried shrimp, and a drizzle of crema.","Garnish with cilantro and serve with lime wedges."],"time":"35 min","serves":4},"fam-c-marinated-lentil-salad-with-zucchini-and":{"ingredients":[{"qty":"1.5 cups","item":"French green lentils, rinsed"},{"qty":"1","item":"zucchini, diced"},{"qty":"2 cups","item":"cherry tomatoes, halved"},{"qty":"1/4","item":"red onion, finely diced"},{"qty":"1/4 cup","item":"extra-virgin olive oil"},{"qty":"3 tbsp","item":"red wine vinegar"},{"qty":"1 clove","item":"garlic, minced"},{"qty":"1 tsp","item":"Dijon mustard"},{"qty":"1/4 cup","item":"fresh parsley, chopped"},{"qty":"1/4 cup","item":"crumbled feta"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Simmer the lentils in salted water until tender but firm, about 20 minutes, then drain and cool.","Whisk together the olive oil, vinegar, garlic, and Dijon to make the dressing.","Combine the lentils, zucchini, tomatoes, and red onion in a bowl.","Toss with the dressing and parsley and let marinate 30 minutes.","Season, top with feta, and serve."],"time":"40 min","serves":4},"fam-c-best-primavera-stuffed-chicken-recipe":{"ingredients":[{"qty":"4","item":"boneless chicken breasts"},{"qty":"1","item":"zucchini, finely diced"},{"qty":"1","item":"red bell pepper, finely diced"},{"qty":"1/2 cup","item":"cherry tomatoes, chopped"},{"qty":"1 cup","item":"shredded mozzarella"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1/4 cup","item":"grated Parmesan"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 400F.","Saute the zucchini, bell pepper, tomatoes, and garlic with Italian seasoning until softened, then cool and mix with the mozzarella.","Cut a deep pocket into each chicken breast and stuff with the vegetable filling.","Rub the chicken with olive oil, salt, pepper, and Parmesan and secure with toothpicks.","Sear in an oven-safe skillet, then bake 20-25 minutes until cooked through.","Rest 5 minutes before serving."],"time":"50 min","serves":4},"fam-c-chicken-enchilada-soup":{"ingredients":[{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 lb","item":"boneless chicken breast"},{"qty":"1 can (10 oz)","item":"red enchilada sauce"},{"qty":"1 can (15 oz)","item":"black beans, drained"},{"qty":"1 can (15 oz)","item":"diced tomatoes"},{"qty":"1 cup","item":"corn kernels"},{"qty":"4 cups","item":"chicken broth"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"chili powder"},{"qty":"1 cup","item":"shredded cheddar"},{"qty":"for serving","item":"tortilla strips, cilantro, lime"}],"steps":["Heat the oil and saute the onion and garlic until softened.","Add the chicken, enchilada sauce, beans, tomatoes, corn, broth, cumin, and chili powder.","Simmer 20 minutes until the chicken is cooked, then remove, shred, and return it to the pot.","Stir in the cheddar until melted and creamy.","Serve topped with tortilla strips, cilantro, and a squeeze of lime."],"time":"40 min","serves":6},"fam-c-best-loaded-baked-potatoes-with-bacon-an":{"ingredients":[{"qty":"4","item":"large russet potatoes"},{"qty":"1 tbsp","item":"olive oil"},{"qty":"6 strips","item":"bacon, cooked and crumbled"},{"qty":"1.5 cups","item":"shredded cheddar"},{"qty":"1/2 cup","item":"sour cream"},{"qty":"4 tbsp","item":"butter"},{"qty":"3","item":"green onions, sliced"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Preheat oven to 425F, rub the potatoes with oil and salt, and pierce all over.","Bake directly on the rack for 50-60 minutes until tender.","Split each potato open and fluff the insides with a fork, adding butter, salt, and pepper.","Top with cheddar and return to the oven until melted.","Finish with sour cream, crumbled bacon, and green onions."],"time":"1 hr 10 min","serves":4},"fam-c-shrimp-stew":{"ingredients":[{"qty":"1.5 lb","item":"shrimp, peeled"},{"qty":"1/4 cup","item":"vegetable oil"},{"qty":"1/4 cup","item":"all-purpose flour"},{"qty":"1","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2 stalks","item":"celery, chopped"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"3 cups","item":"seafood or chicken stock"},{"qty":"1 tsp","item":"cayenne pepper"},{"qty":"3","item":"green onions, sliced"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"cooked white rice"}],"steps":["Make a peanut-butter-colored roux by whisking the oil and flour over medium heat, about 10 minutes.","Add the onion, bell pepper, celery, and garlic and cook until softened.","Stir in the tomatoes, stock, and cayenne and simmer 20 minutes.","Add the shrimp and cook until pink and just done, about 5 minutes.","Stir in the green onions, season, and serve over rice."],"time":"45 min","serves":4},"fam-c-best-ratatouille-with-chickpeas-and-quin":{"ingredients":[{"qty":"1 cup","item":"quinoa, rinsed"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1","item":"eggplant, cubed"},{"qty":"1","item":"zucchini, cubed"},{"qty":"1","item":"red bell pepper, chopped"},{"qty":"1 can (15 oz)","item":"chickpeas, drained"},{"qty":"1 can (28 oz)","item":"crushed tomatoes"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"1 tsp","item":"herbes de Provence"},{"qty":"2 tbsp","item":"fresh basil, chopped"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Cook the quinoa in 2 cups water until fluffy, about 15 minutes.","Heat the oil and saute the onion and garlic until softened.","Add the eggplant, zucchini, and bell pepper and cook until starting to brown, about 8 minutes.","Stir in the chickpeas, crushed tomatoes, thyme, and herbes de Provence and simmer 20 minutes.","Season, stir in the basil, and serve over the quinoa."],"time":"50 min","serves":4},"fam-c-20-minute-shrimp-pasta-mediterranean-sty":{"ingredients":[{"qty":"12 oz","item":"linguine or spaghetti"},{"qty":"1 lb","item":"large shrimp, peeled and deveined"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"4 cloves","item":"garlic, thinly sliced"},{"qty":"1/2 tsp","item":"red pepper flakes"},{"qty":"1 cup","item":"cherry tomatoes, halved"},{"qty":"1/3 cup","item":"Kalamata olives, pitted and halved"},{"qty":"2 tbsp","item":"capers, drained"},{"qty":"1/4 cup","item":"dry white wine"},{"qty":"1/2 cup","item":"crumbled feta cheese"},{"qty":"1/4 cup","item":"fresh parsley, chopped"},{"qty":"1","item":"lemon, juiced and zested"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Bring a large pot of salted water to a boil and cook the pasta until al dente; reserve 1/2 cup pasta water before draining.","While pasta cooks, heat olive oil in a large skillet over medium-high heat and add the garlic and red pepper flakes, cooking until fragrant, about 1 minute.","Add the shrimp, season with salt and pepper, and cook 2 minutes per side until pink and just opaque; remove and set aside.","Add cherry tomatoes, olives, capers, and white wine to the skillet and simmer 3 minutes until the tomatoes soften.","Return the shrimp to the pan, add the drained pasta, lemon juice, zest, and a splash of pasta water, and toss to coat.","Remove from heat, fold in feta and parsley, and serve immediately."],"time":"20 min","serves":4},"fam-c-popeyes-chicken-copycat":{"ingredients":[{"qty":"8","item":"bone-in chicken pieces (thighs, drumsticks, breasts)"},{"qty":"2 cups","item":"buttermilk"},{"qty":"2 tbsp","item":"hot sauce"},{"qty":"2 cups","item":"all-purpose flour"},{"qty":"1 tbsp","item":"paprika"},{"qty":"2 tsp","item":"cayenne pepper"},{"qty":"1 tbsp","item":"garlic powder"},{"qty":"1 tbsp","item":"onion powder"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"2 tsp","item":"salt"},{"qty":"1 tsp","item":"black pepper"},{"qty":"4 cups","item":"vegetable oil, for frying"}],"steps":["Whisk together buttermilk and hot sauce, add the chicken, and marinate in the refrigerator at least 4 hours or overnight.","In a large bowl, combine flour, paprika, cayenne, garlic powder, onion powder, oregano, salt, and pepper.","Working one piece at a time, lift chicken from the buttermilk and dredge thoroughly in the seasoned flour, pressing to adhere; let rest 10 minutes.","Heat oil in a deep heavy pot to 350F (175C).","Fry chicken in batches without crowding, 12 to 15 minutes, turning occasionally, until deep golden and the internal temperature reaches 165F.","Drain on a wire rack and season lightly with salt while hot."],"time":"45 min","serves":4},"fam-c-easy-slow-cooker-smothered-chicken":{"ingredients":[{"qty":"6","item":"bone-in chicken thighs"},{"qty":"1 tsp","item":"paprika"},{"qty":"1 tsp","item":"garlic powder"},{"qty":"1/2 tsp","item":"onion powder"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"vegetable oil"},{"qty":"1 large","item":"onion, sliced"},{"qty":"2 cups","item":"chicken broth"},{"qty":"1 can (10.5 oz)","item":"cream of chicken soup"},{"qty":"3 tbsp","item":"all-purpose flour"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Season the chicken thighs with paprika, garlic powder, onion powder, salt, and pepper.","Heat oil in a skillet over medium-high and sear the chicken until browned on both sides, about 3 minutes per side, then transfer to the slow cooker.","Scatter the sliced onion over the chicken.","Whisk together the chicken broth, cream of chicken soup, and flour until smooth, then pour over the chicken.","Cover and cook on low for 6 hours or high for 3 hours, until the chicken is tender.","Stir the gravy, garnish with parsley, and serve over rice or mashed potatoes."],"time":"6 hr 15 min","serves":6},"fam-c-italian-pork-tenderloin":{"ingredients":[{"qty":"1.5 lb","item":"pork tenderloin"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"fresh rosemary, chopped"},{"qty":"1 tbsp","item":"fresh thyme leaves"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1/2 tsp","item":"red pepper flakes"},{"qty":"1","item":"lemon, zested"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"1/2 cup","item":"chicken broth"}],"steps":["Preheat the oven to 400F (200C).","Combine olive oil, garlic, rosemary, thyme, oregano, red pepper flakes, lemon zest, salt, and pepper into a paste and rub all over the tenderloin.","Heat an oven-safe skillet over medium-high heat and sear the pork on all sides until browned, about 6 minutes total.","Pour the chicken broth into the skillet and transfer to the oven.","Roast 18 to 22 minutes until the internal temperature reaches 145F.","Rest the pork 5 minutes, then slice and spoon the pan juices over the top."],"time":"40 min","serves":4},"fam-c-garlicky-greek-spaghetti-toss":{"ingredients":[{"qty":"1 lb","item":"spaghetti"},{"qty":"1/3 cup","item":"olive oil"},{"qty":"6 cloves","item":"garlic, thinly sliced"},{"qty":"1/2 tsp","item":"red pepper flakes"},{"qty":"1 cup","item":"cherry tomatoes, halved"},{"qty":"1/2 cup","item":"Kalamata olives, pitted"},{"qty":"3/4 cup","item":"crumbled feta cheese"},{"qty":"2 cups","item":"baby spinach"},{"qty":"1","item":"lemon, juiced"},{"qty":"1/4 cup","item":"fresh dill, chopped"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Cook spaghetti in salted boiling water until al dente; reserve 1/2 cup pasta water, then drain.","Heat olive oil in a large skillet over medium heat and gently cook the garlic and red pepper flakes until golden and fragrant, about 2 minutes.","Add cherry tomatoes and olives and cook 3 minutes until the tomatoes begin to break down.","Add the spinach and stir until wilted.","Add the drained pasta, lemon juice, and a splash of pasta water, tossing to coat.","Remove from heat, fold in feta and dill, season with salt and pepper, and serve."],"time":"25 min","serves":4},"fam-c-hot-fudge-brownie-bread-2":{"ingredients":[{"qty":"1 cup","item":"all-purpose flour"},{"qty":"3/4 cup","item":"unsweetened cocoa powder"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1/2 tsp","item":"baking powder"},{"qty":"1/2 tsp","item":"salt"},{"qty":"2","item":"large eggs"},{"qty":"1/2 cup","item":"unsalted butter, melted"},{"qty":"1/3 cup","item":"vegetable oil"},{"qty":"2 tsp","item":"vanilla extract"},{"qty":"1/2 cup","item":"milk"},{"qty":"1 cup","item":"semisweet chocolate chips"},{"qty":"1/2 cup","item":"hot fudge sauce, warmed"}],"steps":["Preheat the oven to 350F (175C) and grease a 9x5-inch loaf pan.","Whisk together flour, cocoa powder, sugar, baking powder, and salt in a large bowl.","In another bowl, whisk the eggs, melted butter, oil, vanilla, and milk until smooth.","Stir the wet ingredients into the dry just until combined, then fold in the chocolate chips.","Pour the batter into the loaf pan and bake 45 to 50 minutes until a toothpick comes out with moist crumbs.","Cool 15 minutes, then drizzle generously with warm hot fudge sauce before slicing."],"time":"1 hr 10 min","serves":8},"fam-c-chef-johns-stuffed-peppers":{"ingredients":[{"qty":"4 large","item":"bell peppers, tops cut and seeded"},{"qty":"1 lb","item":"ground beef"},{"qty":"1 cup","item":"cooked white rice"},{"qty":"1","item":"onion, finely diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 can (15 oz)","item":"tomato sauce, divided"},{"qty":"1 tsp","item":"dried oregano"},{"qty":"1 tsp","item":"paprika"},{"qty":"1/2 tsp","item":"red pepper flakes"},{"qty":"1 cup","item":"shredded mozzarella or Monterey Jack"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Preheat the oven to 375F (190C).","Brown the ground beef in a skillet over medium-high heat, then add the onion and garlic and cook until softened, about 5 minutes.","Stir in the cooked rice, half the tomato sauce, oregano, paprika, red pepper flakes, salt, and pepper.","Stand the peppers in a baking dish and fill each with the beef-rice mixture.","Spoon the remaining tomato sauce over the tops and cover the dish with foil.","Bake 35 minutes, then uncover, top with cheese, and bake 10 more minutes until melted and the peppers are tender."],"time":"1 hr","serves":4},"fam-c-an-exquisite-bowl-of-seafood-gumbo-doesn":{"ingredients":[{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"1 large","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"6 cups","item":"seafood or chicken stock"},{"qty":"12 oz","item":"andouille sausage, sliced"},{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"1/2 lb","item":"lump crab meat"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"2","item":"bay leaves"},{"qty":"1 cup","item":"sliced okra"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Make a roux by whisking the oil and flour in a heavy pot over medium heat, stirring constantly for 20 to 30 minutes until deep chocolate brown.","Add the onion, bell pepper, celery, and garlic and cook until softened, about 8 minutes.","Slowly whisk in the stock, then add the andouille sausage, Cajun seasoning, and bay leaves.","Simmer uncovered for 45 minutes, stirring occasionally, then add the okra and cook 15 minutes more.","Add the shrimp and crab meat and simmer 5 minutes until the shrimp are just cooked through.","Season with salt and pepper, discard the bay leaves, and serve over rice."],"time":"1 hr 45 min","serves":6},"fam-c-best-spicy-shrimp-with-creamy-polenta-re":{"ingredients":[{"qty":"1 cup","item":"polenta or coarse cornmeal"},{"qty":"4 cups","item":"water or chicken broth"},{"qty":"1/2 cup","item":"grated Parmesan cheese"},{"qty":"2 tbsp","item":"butter"},{"qty":"1 lb","item":"large shrimp, peeled and deveined"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1/2 tsp","item":"cayenne pepper"},{"qty":"1/4 cup","item":"heavy cream"},{"qty":"2 tbsp","item":"fresh parsley, chopped"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Bring the water or broth to a boil, then whisk in the polenta and reduce heat to low.","Cook the polenta, stirring often, for 25 to 30 minutes until thick and creamy, then stir in the Parmesan, butter, and a splash of cream; season and keep warm.","Toss the shrimp with smoked paprika, cayenne, salt, and pepper.","Heat olive oil in a skillet over medium-high heat, add the garlic, then the shrimp, cooking 2 minutes per side until pink and just cooked.","Spoon the creamy polenta into bowls, top with the spicy shrimp, and garnish with parsley."],"time":"40 min","serves":4},"fam-c-biscuits-and-gravy-casserole---lemon-sug":{"ingredients":[{"qty":"1 lb","item":"breakfast sausage"},{"qty":"1 can (16.3 oz)","item":"refrigerated biscuits, quartered"},{"qty":"6","item":"large eggs"},{"qty":"1/2 cup","item":"milk"},{"qty":"1 cup","item":"shredded cheddar cheese"},{"qty":"3 tbsp","item":"all-purpose flour"},{"qty":"2 cups","item":"milk, for gravy"},{"qty":"1/2 tsp","item":"garlic powder"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Preheat the oven to 350F (175C) and grease a 9x13-inch baking dish.","Brown the sausage in a skillet over medium heat, then remove half and set aside, leaving the rest with the drippings in the pan.","Make the gravy by stirring the flour into the sausage and drippings, then gradually whisk in 2 cups milk and cook until thickened; season with garlic powder, salt, and pepper.","Scatter the quartered biscuits in the baking dish and top with the reserved browned sausage.","Whisk the eggs with 1/2 cup milk and pour over the biscuits, then sprinkle with cheddar.","Pour the gravy evenly over the top and bake 35 to 40 minutes until set and golden."],"time":"55 min","serves":8},"fam-c-smothered-chicken-queso-casserole":{"ingredients":[{"qty":"1.5 lb","item":"boneless chicken breasts, cubed"},{"qty":"1 tbsp","item":"taco seasoning"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"red bell pepper, diced"},{"qty":"1 can (10 oz)","item":"diced tomatoes with green chiles"},{"qty":"2 cups","item":"queso or cheese dip"},{"qty":"2 cups","item":"cooked rice"},{"qty":"1.5 cups","item":"shredded Mexican cheese blend"},{"qty":"2 tbsp","item":"fresh cilantro, chopped"}],"steps":["Preheat the oven to 375F (190C) and grease a 9x13-inch baking dish.","Toss the chicken with taco seasoning, then sear in olive oil over medium-high heat until browned, about 6 minutes.","Add the onion and bell pepper and cook until softened, about 5 minutes, then stir in the diced tomatoes with chiles.","Spread the cooked rice in the baking dish, top with the chicken mixture, then pour the queso evenly over the top.","Sprinkle with shredded cheese and bake 20 minutes until bubbly and melted.","Garnish with cilantro before serving."],"time":"45 min","serves":6},"fam-c-creamy-chicken-tortellini-soup":{"ingredients":[{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"2","item":"carrots, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 lb","item":"boneless chicken breast, cubed"},{"qty":"6 cups","item":"chicken broth"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"9 oz","item":"cheese tortellini"},{"qty":"1 cup","item":"heavy cream"},{"qty":"2 cups","item":"baby spinach"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Heat olive oil in a large pot over medium heat and cook the onion, carrots, and celery until softened, about 6 minutes.","Add the garlic and chicken and cook until the chicken is no longer pink on the outside.","Pour in the chicken broth and Italian seasoning and bring to a simmer for 10 minutes until the chicken is cooked through.","Add the tortellini and cook according to package directions, about 7 minutes.","Stir in the heavy cream, spinach, and Parmesan, simmering until the spinach wilts.","Season with salt and pepper and serve hot."],"time":"40 min","serves":6},"fam-c-pork-chops-with-cornbread-stuffing":{"ingredients":[{"qty":"4","item":"bone-in pork chops"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"vegetable oil"},{"qty":"4 cups","item":"cornbread, crumbled"},{"qty":"1","item":"onion, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"3 tbsp","item":"butter"},{"qty":"1 tsp","item":"dried sage"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"1.5 cups","item":"chicken broth"},{"qty":"1","item":"large egg, beaten"}],"steps":["Preheat the oven to 375F (190C) and grease a baking dish.","Season the pork chops with salt and pepper and sear in oil over medium-high heat until browned on both sides, about 3 minutes per side.","Melt the butter in the same skillet and cook the onion and celery until soft, about 5 minutes.","In a bowl, combine the crumbled cornbread, sautéed vegetables, sage, thyme, broth, and beaten egg until moistened.","Spread the stuffing in the baking dish and nestle the pork chops on top.","Cover with foil and bake 25 minutes, then uncover and bake 10 more minutes until the pork reaches 145F."],"time":"55 min","serves":4},"fam-c-turmeric-rice-and-chicken":{"ingredients":[{"qty":"4","item":"bone-in chicken thighs"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"1.5 cups","item":"basmati rice, rinsed"},{"qty":"1.5 tsp","item":"ground turmeric"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"3 cups","item":"chicken broth"},{"qty":"1 tsp","item":"salt"},{"qty":"1/4 cup","item":"fresh cilantro, chopped"}],"steps":["Season the chicken with salt and brown in olive oil in a large skillet over medium-high heat, about 4 minutes per side, then remove.","Add the onion to the skillet and cook until softened, then stir in the garlic and ginger for 1 minute.","Add the rice, turmeric, and cumin and toast for 2 minutes until fragrant.","Pour in the chicken broth and salt, then nestle the chicken back into the rice.","Cover and simmer on low for 20 minutes until the rice is tender and the liquid is absorbed.","Rest 5 minutes off the heat, then fluff the rice and garnish with cilantro."],"time":"45 min","serves":4},"fam-c-camellia-creole-red-beans":{"ingredients":[{"qty":"1 lb","item":"dried red kidney beans, soaked overnight"},{"qty":"12 oz","item":"andouille sausage, sliced"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1","item":"smoked ham hock"},{"qty":"2","item":"bay leaves"},{"qty":"1 tsp","item":"dried thyme"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"8 cups","item":"water or chicken broth"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Drain the soaked beans and set aside.","In a large pot, brown the andouille sausage, then add the onion, bell pepper, and celery and cook until softened, about 6 minutes.","Add the garlic and cook 1 minute, then add the beans, ham hock, bay leaves, thyme, Cajun seasoning, and water.","Bring to a boil, then reduce to a simmer and cook uncovered for 2 to 2.5 hours, stirring occasionally, until the beans are creamy.","Mash some of the beans against the side of the pot to thicken the liquid.","Discard the bay leaves and ham hock bones, season with salt and pepper, and serve over rice."],"time":"3 hr","serves":6},"fam-c-best-lemon-butter-chicken-pasta-recipe":{"ingredients":[{"qty":"12 oz","item":"fettuccine"},{"qty":"1.5 lb","item":"boneless chicken breast, sliced"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"4 tbsp","item":"butter"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"chicken broth"},{"qty":"1/2 cup","item":"heavy cream"},{"qty":"2","item":"lemons, juiced and zested"},{"qty":"1/2 cup","item":"grated Parmesan"},{"qty":"1/4 cup","item":"fresh parsley, chopped"}],"steps":["Cook the fettuccine in salted boiling water until al dente; reserve 1/2 cup pasta water, then drain.","Season the chicken with salt and pepper and sear in olive oil over medium-high heat until golden and cooked through, about 4 minutes per side; remove and set aside.","Melt the butter in the same skillet and cook the garlic until fragrant, about 1 minute.","Pour in the chicken broth, cream, lemon juice, and zest, and simmer 3 minutes until slightly thickened.","Stir in the Parmesan, then add the pasta and chicken, tossing with a splash of pasta water to coat.","Garnish with parsley and serve immediately."],"time":"35 min","serves":4},"fam-c-copycat-costcoTM-double-chocolate-muffin":{"ingredients":[{"qty":"1.75 cups","item":"all-purpose flour"},{"qty":"3/4 cup","item":"unsweetened cocoa powder"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1.5 tsp","item":"baking soda"},{"qty":"1/2 tsp","item":"salt"},{"qty":"2","item":"large eggs"},{"qty":"1 cup","item":"buttermilk"},{"qty":"1/2 cup","item":"vegetable oil"},{"qty":"2 tsp","item":"vanilla extract"},{"qty":"1.5 cups","item":"semisweet chocolate chips, divided"}],"steps":["Preheat the oven to 375F (190C) and line a muffin tin with paper liners.","Whisk together the flour, cocoa powder, sugar, baking soda, and salt in a large bowl.","In another bowl, whisk the eggs, buttermilk, oil, and vanilla until smooth.","Fold the wet ingredients into the dry just until combined, then stir in 1 cup of the chocolate chips.","Divide the batter among the muffin cups, filling nearly full, and sprinkle the remaining chips on top.","Bake 18 to 22 minutes until a toothpick comes out with moist crumbs, then cool 10 minutes."],"time":"35 min","serves":12},"fam-c-creamy-texas-potato-salad":{"ingredients":[{"qty":"3 lb","item":"russet or Yukon gold potatoes, cubed"},{"qty":"1 cup","item":"mayonnaise"},{"qty":"2 tbsp","item":"yellow mustard"},{"qty":"1 tbsp","item":"dill pickle relish"},{"qty":"3","item":"hard-boiled eggs, chopped"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"1/4 cup","item":"red onion, finely diced"},{"qty":"1/4 cup","item":"chopped fresh chives"},{"qty":"1 tsp","item":"paprika"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Place the cubed potatoes in a pot of salted water, bring to a boil, and cook until fork-tender, about 12 minutes; drain and cool slightly.","In a large bowl, whisk together the mayonnaise, mustard, and pickle relish.","Add the warm potatoes, chopped eggs, celery, and red onion, folding gently to combine.","Season with salt and pepper, then refrigerate at least 1 hour to chill.","Before serving, sprinkle with paprika and fresh chives."],"time":"30 min plus chilling","serves":8},"fam-c-slow-cooker-chicken-curry-recipe-with-po":{"ingredients":[{"qty":"1.5 lb","item":"boneless chicken thighs, cubed"},{"qty":"2","item":"potatoes, cubed"},{"qty":"2 cups","item":"cauliflower florets"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 tbsp","item":"fresh ginger, grated"},{"qty":"3 tbsp","item":"curry powder"},{"qty":"1 can (14 oz)","item":"coconut milk"},{"qty":"1 can (14 oz)","item":"diced tomatoes"},{"qty":"1 cup","item":"chicken broth"},{"qty":"1 tsp","item":"salt"},{"qty":"1/4 cup","item":"fresh cilantro, chopped"}],"steps":["Place the chicken, potatoes, cauliflower, and onion in the slow cooker.","Add the garlic, ginger, curry powder, coconut milk, diced tomatoes, broth, and salt, stirring to combine.","Cover and cook on low for 6 hours or high for 3 hours, until the chicken and potatoes are tender.","Stir gently and adjust seasoning to taste.","Garnish with cilantro and serve over steamed rice."],"time":"6 hr 15 min","serves":6},"fam-c-gumbo-ya-ya":{"ingredients":[{"qty":"1 cup","item":"vegetable oil"},{"qty":"1 cup","item":"all-purpose flour"},{"qty":"1 lb","item":"boneless chicken thighs, cubed"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"1 large","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"2 stalks","item":"celery, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"6 cups","item":"chicken stock"},{"qty":"2 tsp","item":"Cajun seasoning"},{"qty":"2","item":"bay leaves"},{"qty":"4","item":"green onions, sliced"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Make a dark roux by whisking the oil and flour in a heavy pot over medium heat for 25 to 35 minutes until deep brown.","Add the onion, bell pepper, celery, and garlic and cook until softened, about 8 minutes.","Stir in the andouille sausage and chicken and cook 5 minutes.","Slowly whisk in the chicken stock, then add the Cajun seasoning and bay leaves.","Simmer uncovered for 1 hour, stirring occasionally, until thickened and the chicken is tender.","Discard the bay leaves, season with salt and pepper, stir in the green onions, and serve over rice."],"time":"2 hr","serves":8},"fam-c-chili-pasta-bake":{"ingredients":[{"qty":"12 oz","item":"pasta (penne or rotini)"},{"qty":"1 lb","item":"ground beef"},{"qty":"1","item":"onion, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"2 tbsp","item":"chili powder"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 can (15 oz)","item":"kidney beans, drained"},{"qty":"1 can (15 oz)","item":"diced tomatoes"},{"qty":"1 can (8 oz)","item":"tomato sauce"},{"qty":"2 cups","item":"shredded cheddar cheese"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Preheat the oven to 375F (190C) and grease a 9x13-inch baking dish.","Cook the pasta in salted boiling water until just shy of al dente, then drain.","Brown the ground beef in a skillet, add the onion and garlic, and cook until softened.","Stir in the chili powder, cumin, kidney beans, diced tomatoes, and tomato sauce, and simmer 10 minutes; season with salt and pepper.","Combine the pasta with the chili mixture and half the cheese, then transfer to the baking dish.","Top with the remaining cheese and bake 20 minutes until bubbly and melted."],"time":"50 min","serves":6},"fam-c-healthy-berry-and-spinach-smoothie":{"ingredients":[{"qty":"1 cup","item":"fresh baby spinach"},{"qty":"1 cup","item":"frozen mixed berries"},{"qty":"1","item":"banana"},{"qty":"1 cup","item":"almond milk"},{"qty":"1/2 cup","item":"Greek yogurt"},{"qty":"1 tbsp","item":"chia seeds"},{"qty":"1 tsp","item":"honey (optional)"}],"steps":["Add the almond milk and spinach to a blender and blend until smooth.","Add the frozen berries, banana, Greek yogurt, and chia seeds.","Blend on high until creamy, adding more almond milk if needed to reach your desired consistency.","Taste and add honey if you prefer it sweeter, then pour into glasses and serve immediately."],"time":"5 min","serves":2},"fam-c-crispy-chicken-shawarma":{"ingredients":[{"qty":"2 lb","item":"boneless chicken thighs"},{"qty":"1/4 cup","item":"olive oil"},{"qty":"3 tbsp","item":"lemon juice"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"2 tsp","item":"ground cumin"},{"qty":"2 tsp","item":"paprika"},{"qty":"1 tsp","item":"ground coriander"},{"qty":"1 tsp","item":"ground turmeric"},{"qty":"1/2 tsp","item":"ground cinnamon"},{"qty":"1/2 tsp","item":"cayenne pepper"},{"qty":"1.5 tsp","item":"salt"},{"qty":"4","item":"pita breads, for serving"}],"steps":["Whisk together the olive oil, lemon juice, garlic, cumin, paprika, coriander, turmeric, cinnamon, cayenne, and salt.","Add the chicken thighs, coat thoroughly, and marinate in the refrigerator at least 2 hours or overnight.","Preheat the oven to 425F (220C) and arrange the chicken on a baking sheet.","Roast 30 to 35 minutes until cooked through and the edges are crispy.","For extra crispness, broil 2 to 3 minutes, then rest 5 minutes and slice thinly.","Serve in warm pita with your favorite toppings and sauce."],"time":"50 min plus marinating","serves":6},"fam-c-country-captain-chicken-2":{"ingredients":[{"qty":"8","item":"bone-in chicken thighs"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"3 tbsp","item":"olive oil"},{"qty":"1","item":"onion, diced"},{"qty":"1","item":"green bell pepper, diced"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"2 tbsp","item":"curry powder"},{"qty":"1 can (28 oz)","item":"crushed tomatoes"},{"qty":"1/2 cup","item":"raisins or currants"},{"qty":"1/2 cup","item":"chicken broth"},{"qty":"1/3 cup","item":"sliced almonds, toasted"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Season the chicken with salt and pepper and brown in olive oil in a large skillet over medium-high heat, about 4 minutes per side; remove.","Add the onion and bell pepper to the skillet and cook until softened, about 6 minutes, then add the garlic and curry powder and cook 1 minute.","Stir in the crushed tomatoes, raisins, and chicken broth, then return the chicken to the pan.","Cover and simmer over low heat for 35 to 40 minutes until the chicken is tender.","Garnish with toasted almonds and parsley and serve over rice."],"time":"1 hr","serves":6},"fam-c-spanish-chorizo-stuffed-chicken-breast":{"ingredients":[{"qty":"4","item":"boneless chicken breasts"},{"qty":"6 oz","item":"Spanish chorizo, finely chopped"},{"qty":"1/2 cup","item":"Manchego cheese, grated"},{"qty":"2 tbsp","item":"roasted red pepper, chopped"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"2 cloves","item":"garlic, minced"},{"qty":"1/2 cup","item":"chicken broth"},{"qty":"2 tbsp","item":"fresh parsley, chopped"}],"steps":["Preheat the oven to 400F (200C).","Cut a deep pocket into the side of each chicken breast.","Combine the chorizo, Manchego, and roasted red pepper, then stuff the mixture into each breast and secure with toothpicks.","Season the chicken with smoked paprika, salt, and pepper, then sear in olive oil in an oven-safe skillet until golden, about 3 minutes per side.","Add the garlic and chicken broth to the skillet and transfer to the oven.","Roast 18 to 20 minutes until the chicken reaches 165F, then rest, remove toothpicks, and garnish with parsley."],"time":"45 min","serves":4},"fam-c-mediterranean-style-garlic-shrimp-2":{"ingredients":[{"qty":"1.5 lb","item":"large shrimp, peeled and deveined"},{"qty":"1/4 cup","item":"olive oil"},{"qty":"6 cloves","item":"garlic, minced"},{"qty":"1/2 tsp","item":"red pepper flakes"},{"qty":"1/4 cup","item":"dry white wine"},{"qty":"1","item":"lemon, juiced"},{"qty":"1/4 cup","item":"fresh parsley, chopped"},{"qty":"1/2 cup","item":"cherry tomatoes, halved"},{"qty":"to taste","item":"salt and black pepper"},{"qty":"for serving","item":"crusty bread"}],"steps":["Pat the shrimp dry and season with salt and pepper.","Heat olive oil in a large skillet over medium heat and add the garlic and red pepper flakes, cooking until fragrant, about 1 minute.","Add the cherry tomatoes and cook 2 minutes until they begin to soften.","Add the shrimp and cook 2 minutes per side until pink and just opaque.","Pour in the white wine and lemon juice and simmer 2 minutes until slightly reduced.","Stir in the parsley and serve with crusty bread to soak up the sauce."],"time":"20 min","serves":4},"fam-oreo-cheesecake":{"ingredients":[{"qty":"24","item":"Oreo cookies, divided"},{"qty":"4 tbsp","item":"unsalted butter, melted"},{"qty":"32 oz","item":"cream cheese, softened"},{"qty":"1 cup","item":"granulated sugar"},{"qty":"1 cup","item":"sour cream"},{"qty":"2 tsp","item":"vanilla extract"},{"qty":"4","item":"large eggs"},{"qty":"1/4 cup","item":"heavy cream"}],"steps":["Preheat the oven to 325F (160C) and wrap the outside of a 9-inch springform pan in foil.","Crush 18 Oreos into fine crumbs, mix with the melted butter, and press into the bottom of the pan to form the crust.","Beat the cream cheese and sugar until smooth, then mix in the sour cream and vanilla.","Add the eggs one at a time on low speed, then stir in the heavy cream until just combined.","Roughly chop the remaining 6 Oreos and fold into the batter, then pour over the crust.","Bake in a water bath for 60 to 70 minutes until the center is just set, then cool and refrigerate at least 4 hours before serving."],"time":"1 hr 30 min plus chilling","serves":12},"fam-chicken-enchilada-soup":{"ingredients":[{"qty":"2 lb","item":"ground beef"},{"qty":"1 large","item":"onion, diced"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"3 tbsp","item":"chili powder"},{"qty":"1 tbsp","item":"ground cumin"},{"qty":"1 tsp","item":"smoked paprika"},{"qty":"1 can (15 oz)","item":"kidney beans, drained"},{"qty":"1 can (15 oz)","item":"pinto beans, drained"},{"qty":"1 can (28 oz)","item":"crushed tomatoes"},{"qty":"1 can (6 oz)","item":"tomato paste"},{"qty":"1 cup","item":"beef broth"},{"qty":"to taste","item":"salt and black pepper"}],"steps":["Brown the ground beef in a large pot over medium-high heat, breaking it up, then drain excess fat.","Add the onion and garlic and cook until softened, about 5 minutes.","Stir in the chili powder, cumin, and smoked paprika and cook 1 minute until fragrant.","Add the kidney beans, pinto beans, crushed tomatoes, tomato paste, and beef broth.","Bring to a boil, then reduce heat and simmer uncovered for 45 minutes, stirring occasionally.","Season with salt and pepper and serve with your favorite toppings."],"time":"1 hr","serves":6},"fam-natchitoches-meat-pies":{"ingredients":[{"qty":"1 lb","item":"ground beef"},{"qty":"1/2 lb","item":"ground pork"},{"qty":"1 medium","item":"onion, finely chopped"},{"qty":"1/2","item":"green bell pepper, finely chopped"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"2","item":"green onions, sliced"},{"qty":"1 tbsp","item":"all-purpose flour"},{"qty":"1 tsp","item":"Cajun seasoning"},{"qty":"1/2 tsp","item":"cayenne pepper"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"2 sheets","item":"refrigerated pie crust (or 2 lbs pie dough)"},{"qty":"1","item":"egg, beaten (for egg wash)"},{"qty":"as needed","item":"vegetable oil, for frying"}],"steps":["In a large skillet over medium heat, cook the ground beef and pork, breaking it up, until no longer pink, about 8 minutes.","Add the onion, bell pepper, and garlic and cook until softened, about 5 minutes. Stir in the green onions, Cajun seasoning, cayenne, salt, and pepper.","Sprinkle the flour over the meat, stir well, and cook 2 minutes more. Remove from heat and let the filling cool completely.","Roll out the pie crust and cut into 5-inch rounds. Place a spoonful of filling on each round, brush the edges with egg wash, fold over, and crimp shut with a fork.","Heat 2 inches of oil in a deep skillet to 350°F. Fry the pies a few at a time until golden brown, about 3 minutes per side.","Drain on paper towels and serve warm."],"time":"1 hr 15 min","serves":6},"fam-creole-gumbo":{"ingredients":[{"qty":"3/4 cup","item":"vegetable oil"},{"qty":"3/4 cup","item":"all-purpose flour"},{"qty":"1 large","item":"onion, chopped"},{"qty":"1","item":"green bell pepper, chopped"},{"qty":"2 stalks","item":"celery, chopped"},{"qty":"4 cloves","item":"garlic, minced"},{"qty":"1 lb","item":"andouille sausage, sliced"},{"qty":"1 lb","item":"boneless chicken thighs, cut into chunks"},{"qty":"1 lb","item":"shrimp, peeled and deveined"},{"qty":"6 cups","item":"chicken stock"},{"qty":"2 tbsp","item":"Creole seasoning"},{"qty":"2","item":"bay leaves"},{"qty":"3","item":"green onions, sliced"},{"qty":"to taste","item":"salt and pepper"},{"qty":"for serving","item":"cooked white rice"}],"steps":["In a heavy pot, whisk the oil and flour together over medium heat. Cook, stirring constantly, until the roux turns a deep chocolate-brown color, 20 to 30 minutes.","Add the onion, bell pepper, and celery and cook until softened, about 8 minutes. Stir in the garlic and cook 1 minute more.","Add the andouille sausage and chicken, then slowly whisk in the chicken stock. Add the Creole seasoning and bay leaves.","Bring to a boil, then reduce heat and simmer, stirring occasionally, for 1 hour.","Stir in the shrimp and cook until just pink, about 5 minutes. Discard the bay leaves and stir in the green onions. Season with salt and pepper.","Serve over white rice."],"time":"2 hr","serves":8},"fam-tuscan-tortellini":{"ingredients":[{"qty":"1 tbsp","item":"olive oil"},{"qty":"1 lb","item":"Italian sausage, casings removed"},{"qty":"3 cloves","item":"garlic, minced"},{"qty":"1 cup","item":"sun-dried tomatoes, chopped"},{"qty":"1 1/2 cups","item":"heavy cream"},{"qty":"1/2 cup","item":"chicken broth"},{"qty":"20 oz","item":"refrigerated cheese tortellini"},{"qty":"3 cups","item":"fresh baby spinach"},{"qty":"1/2 cup","item":"grated Parmesan cheese"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"to taste","item":"salt and pepper"}],"steps":["Heat the olive oil in a large skillet over medium-high heat. Add the sausage and cook, breaking it up, until browned, about 6 minutes.","Add the garlic and sun-dried tomatoes and cook until fragrant, about 1 minute.","Pour in the heavy cream and chicken broth, stir, and bring to a gentle simmer.","Add the tortellini and cook, stirring occasionally, until tender, about 5 minutes.","Stir in the spinach, Parmesan, and Italian seasoning. Cook until the spinach wilts and the sauce thickens, about 2 minutes.","Season with salt and pepper and serve."],"time":"30 min","serves":4},"fam-skillet-garlic-knot-chicken":{"ingredients":[{"qty":"4","item":"boneless skinless chicken breasts"},{"qty":"1 tsp","item":"salt"},{"qty":"1/2 tsp","item":"black pepper"},{"qty":"1/2 tsp","item":"Italian seasoning"},{"qty":"2 tbsp","item":"olive oil"},{"qty":"4 tbsp","item":"butter"},{"qty":"6 cloves","item":"garlic, minced"},{"qty":"1 can (16 oz)","item":"refrigerated biscuit dough"},{"qty":"1 cup","item":"shredded mozzarella cheese"},{"qty":"2 tbsp","item":"fresh parsley, chopped"},{"qty":"1/4 cup","item":"grated Parmesan cheese"}],"steps":["Preheat the oven to 375°F. Season the chicken breasts with salt, pepper, and Italian seasoning.","Heat the olive oil in a large oven-safe skillet over medium-high heat. Sear the chicken until golden on both sides, about 4 minutes per side. Remove to a plate.","Lower the heat, add the butter and garlic to the skillet, and cook until fragrant, about 1 minute. Return the chicken to the skillet and spoon the garlic butter over the top.","Cut the biscuit dough into quarters, tie each into a loose knot, and arrange the knots around the chicken in the skillet.","Brush the knots with the garlic butter and sprinkle the mozzarella and Parmesan over everything.","Bake until the chicken is cooked through (165°F) and the knots are golden, 20 to 25 minutes. Sprinkle with parsley and serve."],"time":"45 min","serves":4},"fam-sous-vide-teriyaki-salmon":{"ingredients":[{"qty":"4","item":"salmon fillets (6 oz each)"},{"qty":"1/4 cup","item":"soy sauce"},{"qty":"2 tbsp","item":"mirin"},{"qty":"2 tbsp","item":"sake (or water)"},{"qty":"2 tbsp","item":"brown sugar"},{"qty":"1 tsp","item":"fresh ginger, grated"},{"qty":"1 clove","item":"garlic, grated"},{"qty":"1 tsp","item":"toasted sesame oil"},{"qty":"1 tbsp","item":"sesame seeds, toasted"},{"qty":"2","item":"green onions, sliced"}],"steps":["Set a sous vide water bath to 125°F for medium or 115°F for a softer, rarer texture.","Whisk together the soy sauce, mirin, sake, brown sugar, ginger, garlic, and sesame oil to make the teriyaki marinade.","Place the salmon fillets in a vacuum or zip-top bag with half the marinade. Seal using the water-displacement method and submerge in the bath for 45 minutes.","Meanwhile, simmer the remaining marinade in a small saucepan over medium heat until slightly thickened into a glaze, about 4 minutes.","Remove the salmon from the bag, pat dry, and brush with the teriyaki glaze.","Garnish with sesame seeds and green onions and serve over rice."],"time":"1 hr","serves":4},"fam-southwest-chicken-bake":{"ingredients":[{"qty":"1 1/2 lbs","item":"boneless skinless chicken breasts"},{"qty":"1 can (15 oz)","item":"black beans, drained and rinsed"},{"qty":"1 cup","item":"frozen corn"},{"qty":"1 cup","item":"salsa"},{"qty":"1 tsp","item":"ground cumin"},{"qty":"1 tsp","item":"chili powder"},{"qty":"1/2 tsp","item":"garlic powder"},{"qty":"1 tsp","item":"salt"},{"qty":"1 1/2 cups","item":"shredded Mexican-blend cheese"},{"qty":"1/4 cup","item":"fresh cilantro, chopped"},{"qty":"for serving","item":"sour cream and lime wedges"}],"steps":["Preheat the oven to 400°F and lightly grease a 9x13-inch baking dish.","Place the chicken breasts in the dish and season with cumin, chili powder, garlic powder, and salt.","Scatter the black beans and corn around the chicken, then spoon the salsa evenly over the top.","Cover with foil and bake for 25 minutes.","Remove the foil, sprinkle the cheese over everything, and bake uncovered until the chicken reaches 165°F and the cheese is melted, about 10 minutes more.","Top with cilantro and serve with sour cream and lime wedges."],"time":"45 min","serves":4},"fam-bacon-mozzarella-sticks":{"ingredients":[{"qty":"12 sticks","item":"mozzarella string cheese"},{"qty":"12 slices","item":"bacon"},{"qty":"1/2 cup","item":"all-purpose flour"},{"qty":"2","item":"eggs, beaten"},{"qty":"1 1/2 cups","item":"panko breadcrumbs"},{"qty":"1/2 cup","item":"grated Parmesan cheese"},{"qty":"1 tsp","item":"garlic powder"},{"qty":"1 tsp","item":"Italian seasoning"},{"qty":"as needed","item":"vegetable oil, for frying"},{"qty":"for serving","item":"marinara sauce"}],"steps":["Wrap each mozzarella stick tightly in a slice of bacon, covering the whole stick. Freeze for at least 1 hour so they hold together when fried.","Set up three bowls: flour in the first, beaten eggs in the second, and panko mixed with Parmesan, garlic powder, and Italian seasoning in the third.","Roll each bacon-wrapped stick in flour, then egg, then the panko mixture, pressing to coat well. For a thicker crust, dip in egg and panko a second time.","Heat 2 inches of oil in a deep skillet to 350°F.","Fry the sticks a few at a time, turning, until the bacon is crisp and the coating is golden, about 3 minutes.","Drain on paper towels and serve hot with marinara sauce."],"time":"1 hr 30 min","serves":6}};
